import { create } from 'zustand';
import { supabase } from '../utils/supabase';
import { User, Course, Lesson, Progress, Achievement } from '../types';

interface AppState {
  // User state
  user: User | null;
  isLoading: boolean;
  error: string | null;
  
  // Course state
  courses: Course[];
  currentCourse: Course | null;
  currentLesson: Lesson | null;
  
  // Progress state
  progress: Progress[];
  
  // Achievement state
  achievements: Achievement[];
  userAchievements: Achievement[];
  
  // Actions
  login: (email: string, password: string) => Promise<void>;
  register: (email: string, password: string, name: string) => Promise<void>;
  logout: () => Promise<void>;
  loadUser: () => Promise<void>;
  loadCourses: () => Promise<void>;
  loadCourse: (courseId: number) => Promise<void>;
  loadLesson: (courseId: number, lessonId: number) => Promise<void>;
  loadProgress: () => Promise<void>;
  updateProgress: (courseId: number, lessonId: number, completed: boolean) => Promise<void>;
  loadAchievements: () => Promise<void>;
  resetError: () => void;
}

export const useStore = create<AppState>((set, get) => ({
  // Initial state
  user: null,
  isLoading: false,
  error: null,
  courses: [],
  currentCourse: null,
  currentLesson: null,
  progress: [],
  achievements: [],
  userAchievements: [],
  
  // Actions
  login: async (email, password) => {
    set({ isLoading: true, error: null });
    const { data, error } = await supabase.auth.signInWithPassword({ email, password });
    
    if (error) {
      set({ error: error.message, isLoading: false });
      return;
    }
    
    if (data.user) {
      set({ user: {
        id: data.user.id,
        email: data.user.email || '',
        name: data.user.user_metadata?.name || '',
        avatar_url: data.user.user_metadata?.avatar_url || '',
        created_at: data.user.created_at,
        last_login: new Date().toISOString()
      }, isLoading: false });
      
      // Load user progress and achievements
      get().loadProgress();
      get().loadAchievements();
    }
  },
  
  register: async (email, password, name) => {
    set({ isLoading: true, error: null });
    const { data, error } = await supabase.auth.signUp({
      email,
      password,
      options: {
        data: { name }
      }
    });
    
    if (error) {
      set({ error: error.message, isLoading: false });
      return;
    }
    
    if (data.user) {
      set({ user: {
        id: data.user.id,
        email: data.user.email || '',
        name: data.user.user_metadata?.name || '',
        avatar_url: data.user.user_metadata?.avatar_url || '',
        created_at: data.user.created_at,
        last_login: new Date().toISOString()
      }, isLoading: false });
    }
  },
  
  logout: async () => {
    set({ isLoading: true });
    const { error } = await supabase.auth.signOut();
    
    if (error) {
      set({ error: error.message, isLoading: false });
      return;
    }
    
    set({ 
      user: null, 
      currentCourse: null, 
      currentLesson: null, 
      progress: [], 
      userAchievements: [],
      isLoading: false 
    });
  },
  
  loadUser: async () => {
    set({ isLoading: true });
    try {
      const { data: { user } } = await supabase.auth.getUser();
      
      if (user) {
        set({ user: {
          id: user.id,
          email: user.email || '',
          name: user.user_metadata?.name || '',
          avatar_url: user.user_metadata?.avatar_url || '',
          created_at: user.created_at,
          last_login: new Date().toISOString()
        }, isLoading: false });
        
        // Load user progress and achievements
        get().loadProgress();
        get().loadAchievements();
      } else {
        set({ isLoading: false });
      }
    } catch (error) {
      console.error('加载用户失败:', error);
      set({ isLoading: false });
    }
  },
  
  loadCourses: async () => {
    set({ isLoading: true });
    try {
      const { data, error } = await supabase.from('courses').select('*').order('level');
      
      if (error) {
        set({ error: error.message, isLoading: false });
        return;
      }
      
      set({ courses: data || [], isLoading: false });
    } catch (error) {
      console.error('加载课程失败:', error);
      set({ isLoading: false });
    }
  },
  
  loadCourse: async (courseId) => {
    set({ isLoading: true });
    try {
      const { data, error } = await supabase
        .from('courses')
        .select('*, lessons(*)')
        .eq('id', courseId)
        .single();
      
      if (error) {
        set({ error: error.message, isLoading: false });
        return;
      }
      
      set({ currentCourse: data, isLoading: false });
    } catch (error) {
      console.error('加载课程详情失败:', error);
      set({ isLoading: false });
    }
  },
  
  loadLesson: async (courseId, lessonId) => {
    set({ isLoading: true });
    try {
      // 模拟数据 - 实际项目中应该从数据库获取
      const mockLessons = {
        1: [
          { id: 1, course_id: 1, title: 'Python环境搭建', content: 'Python环境搭建是学习Python的第一步。在本课时中，我们将详细学习：\n\n1. Python的安装方法：\n   - 从官方网站下载并安装Python\n   - 配置环境变量\n   - 验证安装是否成功\n\n2. 开发环境选择：\n   - 命令行终端\n   - IDLE（Python自带编辑器）\n   - Visual Studio Code\n   - PyCharm\n\n3. Jupyter Notebook的安装和使用：\n   - 安装Jupyter Notebook\n   - 创建和运行Notebook\n   - Markdown语法基础\n\n4. 第一个Python程序：\n   - 输出"Hello, World!"\n   - 基本的交互式命令\n\n通过本课时的学习，您将能够搭建一个完整的Python开发环境，并开始编写和运行Python代码。', pitfalls: '1. 环境变量配置：环境变量的配置是初学者的常见难点，需要理解系统路径和环境变量的作用机制。\n2. 版本兼容性：不同Python版本之间的兼容性问题，特别是第三方库的版本要求。\n3. 开发环境选择：选择适合自己的开发环境，需要考虑功能、性能和学习曲线。\n4. Jupyter Notebook依赖：Jupyter Notebook的安装需要处理多个依赖包的版本兼容性。\n5. 权限管理：在不同操作系统中，安装和运行Python时的权限管理问题。', order: 1, duration: '45分钟' },
          { id: 2, course_id: 1, title: 'Python基础语法', content: 'Python基础语法是Python编程的基础。在本课时中，我们将详细学习：\n\n1. 基本数据类型：\n   - 整数、浮点数、字符串\n   - 布尔值\n   - 列表、元组、字典、集合\n\n2. 变量和赋值：\n   - 变量命名规则\n   - 多重赋值\n   - 变量类型转换\n\n3. 运算符：\n   - 算术运算符\n   - 比较运算符\n   - 逻辑运算符\n   - 成员运算符\n\n4. 控制流：\n   - if-elif-else条件语句\n   - for循环\n   - while循环\n   - break和continue语句\n\n5. 输入输出：\n   - print()函数\n   - input()函数\n   - 格式化输出\n\n通过本课时的学习，您将掌握Python的基本语法，能够编写简单的Python程序。', pitfalls: '1. 缩进规则：Python的缩进是语法的一部分，初学者容易在不同编辑器中出现缩进不一致的问题。\n2. 类型系统：Python是动态类型语言，初学者需要理解变量类型的自动转换和类型检查。\n3. 控制流逻辑：复杂条件语句和循环的逻辑设计是初学者的常见难点。\n4. 字符串操作：字符串的格式化、拼接和转义字符的使用需要特别注意。\n5. 运算符优先级：不同运算符的优先级容易混淆，导致表达式计算结果不符合预期。', order: 2, duration: '60分钟' },
          { id: 3, course_id: 1, title: 'Python函数和模块', content: 'Python函数和模块是Python编程的重要组成部分。在本课时中，我们将详细学习：\n\n1. 函数定义和调用：\n   - def关键字\n   - 函数参数\n   - 默认参数\n   - 可变参数\n   - 函数返回值\n\n2. 作用域：\n   - 局部变量\n   - 全局变量\n   - nonlocal关键字\n\n3. 模块：\n   - 模块导入\n   - __name__变量\n   - 包的概念\n\n4. 常用内置函数：\n   - len()、max()、min()\n   - range()、list()、dict()\n   - zip()、enumerate()\n\n通过本课时的学习，您将能够定义和使用函数，以及创建和使用模块，提高代码的复用性和可维护性。', pitfalls: '1. 函数参数传递：理解Python的参数传递机制（传值还是传引用）是一个常见难点。\n2. 作用域规则：局部变量、全局变量和nonlocal变量的作用域规则容易混淆。\n3. 模块导入机制：理解Python的模块导入机制和包的概念需要一定的时间。\n4. 可变参数处理：*args和**kwargs的使用方法和场景需要深入理解。\n5. 默认参数陷阱：使用可变对象作为默认参数会导致意外的共享状态。', order: 3, duration: '60分钟' },
          { id: 4, course_id: 1, title: 'NumPy基础', content: 'NumPy是Python中用于科学计算的重要库。在本课时中，我们将详细学习：\n\n1. NumPy简介：\n   - NumPy的安装\n   - NumPy的核心概念\n\n2. 数组创建：\n   - 从列表创建\n   - 内置函数创建（zeros、ones、arange等）\n   - 随机数生成\n\n3. 数组属性：\n   - shape、dtype、size\n   - ndim\n\n4. 数组索引和切片：\n   - 基本索引\n   - 切片操作\n   - 布尔索引\n   - 花式索引\n\n5. 数组操作：\n   - 基本运算\n   - 广播机制\n   - 常用数学函数\n\n通过本课时的学习，您将掌握NumPy的基本使用方法，为后续的数据分析打下基础。', pitfalls: '1. 广播机制：NumPy的广播规则是一个重要难点，需要理解不同形状数组之间的运算规则。\n2. 索引和切片：NumPy的高级索引（布尔索引、花式索引）与基本索引的区别和使用场景。\n3. 数据类型管理：理解NumPy的数据类型系统及其对内存使用和计算效率的影响。\n4. 视图与副本：区分数组操作是返回视图还是副本，避免意外修改原始数据。\n5. 内存优化：处理大型数组时的内存管理和性能优化策略。', order: 4, duration: '60分钟' },
          { id: 5, course_id: 1, title: 'Pandas基础', content: 'Pandas是Python中用于数据处理和分析的重要库。在本课时中，我们将详细学习：\n\n1. Pandas简介：\n   - Pandas的安装\n   - Pandas的核心数据结构\n\n2. Series：\n   - Series的创建\n   - Series的索引和切片\n   - Series的基本操作\n\n3. DataFrame：\n   - DataFrame的创建\n   - DataFrame的索引和切片\n   - DataFrame的基本操作\n   - 数据类型转换\n\n4. 数据读取和写入：\n   - 读取CSV文件\n   - 读取Excel文件\n   - 写入数据\n\n5. 数据清洗：\n   - 处理缺失值\n   - 处理重复值\n   - 数据排序\n\n通过本课时的学习，您将掌握Pandas的基本使用方法，能够处理和分析实际的数据集。', pitfalls: '1. 索引体系：Pandas的索引体系较为复杂，包括标签索引、位置索引和多级索引。\n2. 数据类型管理：理解Pandas的数据类型系统及其对内存使用和计算效率的影响。\n3. 缺失值处理：选择合适的缺失值处理方法，平衡数据完整性和分析准确性。\n4. 索引对齐：Pandas的自动索引对齐特性可能导致意外的结果，需要特别注意。\n5. 内存优化：处理大型数据集时的内存管理和性能优化策略。', order: 5, duration: '60分钟' },
          { id: 6, course_id: 1, title: '数据可视化基础', content: '数据可视化是数据分析的重要组成部分。在本课时中，我们将详细学习：\n\n1. Matplotlib简介：\n   - Matplotlib的安装\n   - 基本概念\n\n2. 基本图表类型：\n   - 折线图\n   - 柱状图\n   - 散点图\n   - 饼图\n   - 直方图\n\n3. 图表定制：\n   - 标题和标签\n   - 图例\n   - 颜色和样式\n   - 网格和背景\n\n4. 多子图：\n   - subplot()函数\n   - subplots()函数\n\n5. 中文显示问题：\n   - 字体设置\n   - 负号显示\n\n通过本课时的学习，您将能够创建各种类型的图表，直观地展示数据。', pitfalls: '1. 图表类型选择：选择适合数据类型和分析目标的图表类型是一个重要难点。\n2. 图表定制：掌握Matplotlib的各种定制选项，创建美观且信息丰富的图表。\n3. 中文显示：正确配置中文字体，解决中文显示乱码问题。\n4. 多子图布局：设计合理的多子图布局，展示复杂的数据分析结果。\n5. 颜色选择：选择合适的颜色方案，提高图表的可读性和美观度。', order: 6, duration: '60分钟' },
          { id: 7, course_id: 1, title: '商业数据分析案例', content: '商业数据分析案例是将Python应用于实际商业场景的重要实践。在本课时中，我们将通过一个完整的商业数据分析案例，详细学习：\n\n1. 案例背景：\n   - 电商销售数据\n   - 分析目标\n\n2. 数据收集和导入：\n   - 数据格式\n   - 使用Pandas读取数据\n\n3. 数据清洗和预处理：\n   - 处理缺失值\n   - 数据类型转换\n   - 数据筛选和过滤\n\n4. 数据探索和分析：\n   - 基本统计分析\n   - 按产品类别分析\n   - 按时间趋势分析\n   - 客户购买行为分析\n\n5. 数据可视化：\n   - 销售趋势图\n   - 产品类别分布图\n   - 客户购买行为分析图\n\n6. 分析结论和建议：\n   - 关键发现\n   - 业务建议\n\n通过本课时的学习，您将能够将所学知识应用到实际的商业数据分析场景中。', pitfalls: '1. 分析目标定义：明确商业分析的目标和问题是一个重要难点，直接影响分析的方向和深度。\n2. 数据质量评估：识别和处理数据质量问题，确保分析结果的可靠性。\n3. 分析方法选择：根据业务问题选择合适的分析方法和工具。\n4. 数据可视化设计：创建有效的数据可视化，清晰传达分析结果。\n5. 业务洞察提取：从数据分析中提取有价值的业务洞察，并转化为可执行的建议。', order: 7, duration: '90分钟' },
          { id: 8, course_id: 1, title: '课程总结与项目实践', content: '课程总结与项目实践是对本课程内容的回顾和应用。在本课时中，我们将：\n\n1. 课程内容总结：\n   - Python基础语法\n   - NumPy和Pandas库\n   - 数据可视化\n   - 商业数据分析\n\n2. 项目实践：\n   - 项目目标：分析销售数据，识别销售趋势和客户行为\n   - 数据准备：使用提供的销售数据集\n   - 分析步骤：\n     * 数据导入和清洗\n     * 数据探索和分析\n     * 数据可视化\n     * 生成分析报告\n\n3. 学习资源推荐：\n   - 书籍\n   - 在线课程\n   - 文档和社区\n\n4. 后续学习方向：\n   - 高级Python编程\n   - 机器学习基础\n   - 深度学习入门\n   - 大数据处理\n\n通过本课时的学习，您将巩固所学知识，并完成一个完整的商业数据分析项目。', pitfalls: '1. 项目规划：制定合理的项目计划和时间安排，确保项目能够按时完成。\n2. 数据管理：有效地组织和管理项目数据，确保数据的质量和一致性。\n3. 技术整合：将所学的各种技术和工具整合到实际项目中。\n4. 代码质量：编写清晰、可维护的代码，遵循良好的编程实践。\n5. 报告编写：创建结构清晰、内容详实的分析报告，有效传达分析结果。\n6. 持续学习：建立持续学习的习惯，不断提升数据分析技能。', order: 8, duration: '90分钟' }
        ],
        2: [
          { id: 1, course_id: 2, title: '数据分析概述', content: '数据分析概述是Python数据分析实战的第一课时。在本课时中，我们将详细学习：\n\n1. 数据分析的基本概念：\n   - 什么是数据分析\n   - 数据分析的重要性\n   - 数据分析的应用领域\n\n2. 数据分析的基本流程：\n   - 问题定义\n   - 数据收集\n   - 数据清洗\n   - 数据探索\n   - 数据建模\n   - 结果分析\n   - 报告生成\n\n3. 数据分析的工具和技术：\n   - Python生态系统\n   - 常用库介绍（NumPy、Pandas、Matplotlib等）\n   - 开发环境搭建\n\n4. 数据分析的职业发展：\n   - 数据分析师的职责\n   - 所需技能和能力\n   - 职业发展路径\n\n通过本课时的学习，您将对数据分析有一个全面的认识，为后续的学习打下基础。', pitfalls: '1. 分析思维培养：建立系统化的数据分析思维，从问题定义到结果应用的完整思考过程。\n2. 工具生态系统：理解Python数据分析生态系统的组成和各工具的适用场景。\n3. 流程理解：掌握数据分析的完整流程，确保分析的系统性和完整性。\n4. 业务理解：将技术分析与业务需求相结合，确保分析结果的实际价值。\n5. 技能规划：根据职业发展路径，有针对性地提升数据分析技能。', order: 1, duration: '45分钟' },
          { id: 2, course_id: 2, title: '数据导入与导出', content: '数据导入与导出是数据分析的基础步骤。在本课时中，我们将详细学习：\n\n1. 数据格式介绍：\n   - CSV格式\n   - Excel格式\n   - JSON格式\n   - SQL数据库\n   - 其他格式（TXT、XML等）\n\n2. 使用Pandas导入数据：\n   - read_csv()函数\n   - read_excel()函数\n   - read_json()函数\n   - read_sql()函数\n   - 导入参数设置\n\n3. 数据导出：\n   - to_csv()函数\n   - to_excel()函数\n   - to_json()函数\n   - to_sql()函数\n   - 导出参数设置\n\n4. 数据导入导出的常见问题：\n   - 编码问题\n   - 分隔符问题\n   - 数据类型问题\n   - 大文件处理\n\n通过本课时的学习，您将掌握各种数据格式的导入和导出方法，为后续的数据分析做好准备。', pitfalls: '1. 编码处理：处理不同编码格式的文件，确保数据正确读取。\n2. 大文件处理：高效处理大型数据集，避免内存不足问题。\n3. 数据类型控制：手动指定和调整数据类型，确保分析的准确性。\n4. 参数优化：根据不同数据格式和需求，优化Pandas导入导出参数。\n5. 数据库连接：建立和管理与SQL数据库的连接，实现数据的高效读写。', order: 2, duration: '60分钟' },
          { id: 3, course_id: 2, title: '数据清洗基础', content: '数据清洗是数据分析的关键步骤。在本课时中，我们将详细学习：\n\n1. 数据质量评估：\n   - 数据完整性检查\n   - 数据一致性检查\n   - 数据准确性检查\n   - 数据时效性检查\n\n2. 缺失值处理：\n   - 缺失值识别\n   - 缺失值原因分析\n   - 缺失值处理方法（删除、填充、插值等）\n   - 不同处理方法的适用场景\n\n3. 重复值处理：\n   - 重复值识别\n   - 重复值处理方法\n   - 重复值处理的注意事项\n\n4. 异常值处理：\n   - 异常值识别方法（统计方法、可视化方法）\n   - 异常值处理方法（删除、替换、保留等）\n   - 异常值处理的影响\n\n5. 数据类型转换：\n   - 数值类型转换\n   - 字符串类型转换\n   - 日期时间类型转换\n   - 分类变量处理\n\n通过本课时的学习，您将掌握数据清洗的基本方法和技巧，提高数据质量。', pitfalls: '1. 数据质量评估：建立系统化的数据质量评估方法，识别和量化数据质量问题。\n2. 缺失值策略：根据数据特点和分析目标，选择合适的缺失值处理策略。\n3. 异常值识别：结合统计方法和业务知识，准确识别异常值。\n4. 数据类型优化：合理选择和转换数据类型，提高数据处理效率和准确性。\n5. 清洗流程设计：设计高效的清洗流程，确保数据清洗的一致性和可重复性。', order: 3, duration: '60分钟' },
          { id: 4, course_id: 2, title: '数据探索分析', content: '数据探索分析是了解数据特征的重要步骤。在本课时中，我们将详细学习：\n\n1. 数据基本信息查看：\n   - shape属性\n   - dtypes属性\n   - info()方法\n   - describe()方法\n\n2. 数值型数据探索：\n   - 基本统计量计算\n   - 分布分析\n   - 相关性分析\n   - 分位数分析\n\n3. 分类型数据探索：\n   - 频次分析\n   - 占比分析\n   - 交叉分析\n   - 卡方检验\n\n4. 时间序列数据探索：\n   - 趋势分析\n   - 季节性分析\n   - 周期性分析\n   - 异常检测\n\n5. 数据可视化探索：\n   - 直方图\n   - 箱线图\n   - 散点图\n   - 热力图\n   - 相关性矩阵图\n\n通过本课时的学习，您将掌握数据探索的基本方法，能够从数据中发现有价值的信息。', pitfalls: '1. 探索策略：制定系统的数据探索策略，确保全面而深入地了解数据特征。\n2. 统计方法选择：根据数据类型和分析目标，选择合适的统计方法进行探索。\n3. 可视化设计：创建有效的可视化图表，突出数据的关键特征和模式。\n4. 业务视角：从业务角度出发，聚焦于对业务决策有价值的信息。\n5. 异常检测：结合统计方法和业务知识，准确识别数据中的异常模式。', order: 4, duration: '60分钟' },
          { id: 5, course_id: 2, title: '数据可视化实践', content: '数据可视化是数据分析的重要组成部分。在本课时中，我们将详细学习：\n\n1. 数据可视化基础：\n   - 可视化的原则\n   - 图表类型选择\n   - 颜色使用技巧\n   - 图表布局设计\n\n2. Matplotlib库使用：\n   - 基本图表创建\n   - 图表定制\n   - 多子图布局\n   - 交互式图表\n\n3. Seaborn库使用：\n   - 统计图表创建\n   - 主题设置\n   - 颜色面板\n   - 高级可视化\n\n4. 实际案例分析：\n   - 销售数据可视化\n   - 客户行为可视化\n   - 市场趋势可视化\n   - 竞争分析可视化\n\n5. 可视化最佳实践：\n   - 简洁明了\n   - 重点突出\n   - 易于理解\n   - 美观大方\n\n通过本课时的学习，您将掌握数据可视化的基本方法和技巧，能够创建有效的数据可视化图表。', pitfalls: '1. 图表类型选择错误：选择了不适合数据类型的图表类型，导致信息传达不清。\n2. 颜色使用不当：使用了不利于色盲人士阅读的颜色组合，或者颜色过多导致混乱。\n3. 图表过于复杂：添加了过多的元素，导致图表难以理解。\n4. 缺乏标题和标签：没有为图表添加清晰的标题和标签，导致读者无法理解图表内容。\n5. 数据失真：通过不当的轴范围或图表类型使数据看起来与实际情况不符。\n6. 忽略交互性：在需要交互的场景中使用了静态图表，降低了用户体验。', order: 5, duration: '60分钟' },
          { id: 6, course_id: 2, title: '统计分析基础', content: '统计分析是数据分析的重要方法。在本课时中，我们将详细学习：\n\n1. 描述性统计：\n   - 集中趋势度量（均值、中位数、众数）\n   - 离散程度度量（标准差、方差、四分位数）\n   - 分布形状度量（偏度、峰度）\n\n2. 推断统计：\n   - 假设检验\n   - 置信区间\n   - p值解释\n   - 统计显著性\n\n3. 相关分析：\n   - 皮尔逊相关系数\n   - 斯皮尔曼等级相关系数\n   - 相关性检验\n   - 相关性可视化\n\n4. 回归分析：\n   - 简单线性回归\n   - 多元线性回归\n   - 回归模型评估\n   - 回归诊断\n\n5. 方差分析：\n   - 单因素方差分析\n   - 多因素方差分析\n   - 事后检验\n\n通过本课时的学习，您将掌握基本的统计分析方法，能够从数据中得出有意义的统计结论。', pitfalls: '1. 统计方法使用不当：使用了不适合数据类型的统计方法，导致结果不可靠。\n2. 样本量不足：在样本量过小的情况下进行统计分析，导致结果不具有代表性。\n3. 假设条件不满足：在不满足统计方法假设条件的情况下使用该方法，导致结果无效。\n4. p值误解：对p值的意义理解错误，导致错误的统计结论。\n5. 多重比较问题：进行多次假设检验时没有校正p值，导致假阳性率增加。\n6. 因果关系混淆：将相关关系误认为因果关系，导致错误的结论。', order: 6, duration: '60分钟' },
          { id: 7, course_id: 2, title: '商业案例分析', content: '商业案例分析是将数据分析应用于实际商业场景的重要实践。在本课时中，我们将详细学习：\n\n1. 案例背景介绍：\n   - 电商销售数据\n   - 分析目标和问题\n   - 数据获取和预处理\n\n2. 销售数据分析：\n   - 销售趋势分析\n   - 产品类别分析\n   - 地区销售分析\n   - 客户购买行为分析\n\n3. 客户分析：\n   - 客户细分\n   - 客户生命周期价值分析\n   - 客户流失分析\n   - 客户满意度分析\n\n4. 市场分析：\n   - 市场份额分析\n   - 竞争对手分析\n   - 市场趋势预测\n   - 机会识别\n\n5. 分析结果与建议：\n   - 关键发现\n   - 业务建议\n   - 实施计划\n   - 效果评估\n\n通过本课时的学习，您将能够将所学的数据分析方法应用到实际的商业场景中。', pitfalls: '1. 数据质量问题：使用了质量差的数据，导致分析结果不可靠。\n2. 分析目标不明确：没有明确的分析目标，导致分析方向混乱。\n3. 过度分析：分析了与业务无关的数据，浪费时间和资源。\n4. 结论不严谨：基于有限的数据得出过于绝对的结论。\n5. 缺乏业务知识：不了解业务背景，导致分析结果与实际业务需求不符。\n6. 报告表达不清：分析报告结构混乱，重点不突出，难以理解。', order: 7, duration: '60分钟' },
          { id: 8, course_id: 2, title: '项目实践准备', content: '项目实践准备是确保数据分析项目成功的重要步骤。在本课时中，我们将详细学习：\n\n1. 项目规划：\n   - 项目目标确定\n   - 项目范围定义\n   - 项目时间线规划\n   - 资源分配\n\n2. 数据准备：\n   - 数据需求分析\n   - 数据收集计划\n   - 数据存储方案\n   - 数据安全考虑\n\n3. 技术栈选择：\n   - 编程语言选择\n   - 库和框架选择\n   - 工具和平台选择\n   - 版本控制\n\n4. 分析方法确定：\n   - 分析方法选择\n   - 模型选择\n   - 评估指标确定\n   - 验证方法\n\n5. 项目管理：\n   - 任务分解\n   - 进度跟踪\n   - 风险评估\n   - 沟通计划\n\n通过本课时的学习，您将掌握数据分析项目的准备工作，为项目实施做好充分准备。', pitfalls: '1. 项目范围过大：选择了过于复杂的项目，导致无法在有限时间内完成。\n2. 数据准备不足：没有充分准备数据，导致分析过程中遇到大量数据问题。\n3. 技术选择不当：选择了不适合项目需求的技术工具，影响项目进展。\n4. 分析方法选择错误：选择了不适合数据类型或问题类型的分析方法。\n5. 缺乏项目管理：没有进行有效的项目管理，导致项目进度拖延。\n6. 沟通不畅：与项目相关方沟通不畅，导致需求理解偏差。', order: 8, duration: '60分钟' },
          { id: 9, course_id: 2, title: '项目实施', content: '项目实施是将数据分析计划转化为实际成果的关键步骤。在本课时中，我们将详细学习：\n\n1. 数据处理：\n   - 数据导入和清洗\n   - 数据转换和整合\n   - 特征工程\n   - 数据质量保证\n\n2. 分析执行：\n   - 探索性分析\n   - 统计分析\n   - 建模和预测\n   - 结果验证\n\n3. 可视化实现：\n   - 图表创建\n   - 仪表板设计\n   - 交互式可视化\n   - 报告生成\n\n4. 代码管理：\n   - 代码组织\n   - 注释和文档\n   - 代码审查\n   - 版本控制\n\n5. 问题解决：\n   - 技术问题排查\n   - 数据问题处理\n   - 性能优化\n   - 错误处理\n\n通过本课时的学习，您将掌握数据分析项目的实施方法，能够顺利完成项目任务。', pitfalls: '1. 数据处理错误：在数据处理过程中出现错误，导致分析结果不准确。\n2. 分析方法应用不当：没有正确应用分析方法，导致结果不可靠。\n3. 代码质量差：代码组织混乱，缺乏注释和文档，难以维护和理解。\n4. 性能问题：分析过程中遇到性能瓶颈，导致项目进度拖延。\n5. 错误处理不足：没有充分考虑可能出现的错误，导致程序崩溃或结果错误。\n6. 结果验证不充分：没有对分析结果进行充分验证，导致错误的结论。', order: 9, duration: '60分钟' },
          { id: 10, course_id: 2, title: '项目展示与总结', content: '项目展示与总结是数据分析项目的最后环节。在本课时中，我们将详细学习：\n\n1. 成果整理：\n   - 分析结果汇总\n   - 关键发现提取\n   - 可视化材料准备\n   - 报告撰写\n\n2. 展示技巧：\n   - 受众分析\n   - 内容组织\n   - 演示方法\n   - 时间管理\n\n3. 沟通技巧：\n   - 清晰表达\n   - 故事讲述\n   - 问答准备\n   - 反馈处理\n\n4. 项目总结：\n   - 项目回顾\n   - 经验教训\n   - 成功因素分析\n   - 改进建议\n\n5. 后续行动：\n   - 实施计划\n   - 监控方案\n   - 持续改进\n   - 知识共享\n\n通过本课时的学习，您将掌握如何有效地展示和总结数据分析项目成果，确保项目价值得到充分体现。', pitfalls: '1. 展示内容过多：在有限的时间内展示过多内容，导致重点不突出。\n2. 技术术语过多：使用了过多的技术术语，导致非技术人员难以理解。\n3. 数据可视化不当：创建了过于复杂或不清晰的可视化图表。\n4. 故事性不足：没有将分析结果组织成一个连贯的故事，导致听众难以跟随。\n5. 问答准备不足：没有充分准备可能的问题，导致在问答环节表现不佳。\n6. 总结不全面：没有全面总结项目经验和教训，无法为未来项目提供参考。', order: 10, duration: '60分钟' }
        ],
        3: [
          { id: 1, course_id: 3, title: '数据采集概述', content: '数据采集概述是数据采集与预处理课程的第一课时。在本课时中，我们将详细学习：\n\n1. 数据采集的基本概念：\n   - 什么是数据采集\n   - 数据采集的重要性\n   - 数据采集的应用场景\n\n2. 数据来源：\n   - 公开数据集\n   - 网络数据\n   - 企业内部数据\n   - 传感器数据\n   - 社交媒体数据\n\n3. 数据采集方法：\n   - 网络爬虫\n   - API接口\n   - 数据购买\n   - 问卷调查\n   - 实验数据采集\n\n4. 数据采集的挑战：\n   - 数据质量\n   - 数据量\n   - 数据格式\n   - 法律和道德问题\n   - 技术挑战\n\n5. 数据采集的最佳实践：\n   - 明确采集目标\n   - 选择合适的采集方法\n   - 确保数据质量\n   - 遵守法律法规\n   - 数据存储和管理\n\n通过本课时的学习，您将对数据采集有一个全面的认识，为后续的学习打下基础。', pitfalls: '1. 目标不明确：没有明确的数据采集目标，导致采集的数据不符合需求。\n2. 方法选择不当：选择了不适合数据类型的采集方法，影响采集效率和质量。\n3. 法律意识淡薄：在采集数据时没有考虑法律法规，可能导致法律风险。\n4. 数据质量忽视：只关注数据量，忽视了数据质量，导致后续分析困难。\n5. 存储规划不足：没有合理规划数据存储，导致数据管理混乱。\n6. 技术准备不足：在开始采集前没有充分准备技术工具，导致采集过程中遇到问题。', order: 1, duration: '45分钟' },
          { id: 2, course_id: 3, title: '网络爬虫基础', content: '网络爬虫基础是数据采集的核心技术之一。在本课时中，我们将详细学习：\n\n1. 网络爬虫的基本概念：\n   - 什么是网络爬虫\n   - 网络爬虫的工作原理\n   - 网络爬虫的类型\n   - 网络爬虫的应用场景\n\n2. 网页结构分析：\n   - HTML基本结构\n   - CSS选择器\n   - XPath表达式\n   - DOM结构\n\n3. 爬虫开发流程：\n   - 确定目标网站\n   - 分析网页结构\n   - 编写爬虫代码\n   - 测试和调试\n   - 部署和监控\n\n4. 爬虫的法律和道德：\n   - robots.txt协议\n   - 网站Terms of Service\n   - 数据使用限制\n   - 爬取频率控制\n\n5. 爬虫的挑战：\n   - 反爬机制\n   - 动态内容\n   - 登录验证\n   - 数据量过大\n   - IP限制\n\n通过本课时的学习，您将掌握网络爬虫的基本原理和技术，为后续的爬虫开发打下基础。', pitfalls: '1. 忽视robots.txt：不遵守网站的robots.txt协议，可能导致法律风险。\n2. 爬取频率过高：爬取速度过快，给目标网站造成压力，可能被封禁。\n3. 网页结构分析错误：没有正确分析网页结构，导致爬虫无法获取数据。\n4. 异常处理不足：没有充分处理网络异常、页面变化等情况，导致爬虫不稳定。\n5. 数据存储不当：没有合理存储爬取的数据，导致数据丢失或管理困难。\n6. 代码质量差：爬虫代码结构混乱，缺乏注释和文档，难以维护。', order: 2, duration: '60分钟' },
          { id: 3, course_id: 3, title: '使用Requests获取数据', content: 'Requests库是Python中用于HTTP请求的重要库。在本课时中，我们将详细学习：\n\n1. Requests库介绍：\n   - 安装和导入\n   - 基本功能\n   - 优势和特点\n\n2. HTTP请求方法：\n   - GET请求\n   - POST请求\n   - PUT请求\n   - DELETE请求\n   - 其他请求方法\n\n3. 请求参数设置：\n   - URL参数\n   - 请求头\n   - 表单数据\n   - JSON数据\n   - 文件上传\n\n4. 响应处理：\n   - 响应状态码\n   - 响应头\n   - 响应内容\n   - JSON解析\n   - 编码处理\n\n5. 高级功能：\n   - 会话管理\n   - Cookie处理\n   - 重定向处理\n   - 超时设置\n   - 代理设置\n\n通过本课时的学习，您将掌握使用Requests库获取网页数据的方法，为网络爬虫开发做好准备。', pitfalls: '1. 请求头设置不当：没有设置合适的请求头，导致被网站识别为爬虫。\n2. 超时设置缺失：没有设置请求超时，导致爬虫在网络问题时卡住。\n3. 异常处理不足：没有处理网络异常、请求失败等情况，导致程序崩溃。\n4. 编码处理错误：没有正确处理响应编码，导致中文显示乱码。\n5. 会话管理不当：没有合理使用会话，导致无法保持登录状态或Cookie。\n6. 代理使用不当：使用了不稳定的代理，导致请求失败或被封禁。', order: 3, duration: '60分钟' },
          { id: 4, course_id: 3, title: '使用BeautifulSoup解析数据', content: 'BeautifulSoup是Python中用于解析HTML和XML的重要库。在本课时中，我们将详细学习：\n\n1. BeautifulSoup介绍：\n   - 安装和导入\n   - 基本功能\n   - 解析器选择\n\n2. HTML解析基础：\n   - 标签选择\n   - 属性选择\n   - 文本提取\n   - 嵌套结构解析\n\n3. CSS选择器：\n   - 标签选择器\n   - 类选择器\n   - ID选择器\n   - 后代选择器\n   - 伪类选择器\n\n4. XPath表达式：\n   - 基本语法\n   - 轴选择\n   - 谓词过滤\n   - 函数使用\n\n5. 数据提取技巧：\n   - 表格数据提取\n   - 列表数据提取\n   - 链接和图片提取\n   - 结构化数据提取\n\n通过本课时的学习，您将掌握使用BeautifulSoup解析HTML数据的方法，能够从网页中提取有价值的信息。', pitfalls: '1. 解析器选择错误：选择了不适合的解析器，导致解析结果不符合预期。\n2. 选择器使用不当：使用了复杂或效率低下的选择器，导致解析速度慢。\n3. 异常处理不足：没有处理HTML结构变化、标签缺失等情况，导致解析失败。\n4. 内存使用过高：解析大型HTML文件时内存不足，导致程序崩溃。\n5. 数据提取不完整：没有考虑到网页结构的变化，导致数据提取不完整。\n6. 代码可读性差：解析代码结构混乱，缺乏注释，难以维护。', order: 4, duration: '60分钟' },
          { id: 5, course_id: 3, title: '使用Selenium爬取动态数据', content: 'Selenium是Python中用于爬取动态加载数据的重要工具。在本课时中，我们将详细学习：\n\n1. Selenium介绍：\n   - 安装和配置\n   - 基本功能\n   - 浏览器驱动\n\n2. WebDriver使用：\n   - 浏览器启动\n   - 页面导航\n   - 元素定位\n   - 元素操作\n   - 等待机制\n\n3. 动态内容处理：\n   - JavaScript渲染\n   - AJAX加载\n   - 滚动加载\n   - 弹窗处理\n\n4. 高级功能：\n   - 登录自动化\n   - 表单提交\n   - 截图功能\n   - 浏览器配置\n   - 无头模式\n\n5. 性能优化：\n   - 元素定位优化\n   - 等待时间优化\n   - 浏览器选项优化\n   - 并发处理\n\n通过本课时的学习，您将掌握使用Selenium爬取动态数据的方法，能够处理复杂的网页交互。', pitfalls: '1. 性能问题：Selenium运行速度慢，处理大量数据时效率低下。\n2. 内存消耗：启动浏览器占用大量内存，可能导致系统资源不足。\n3. 元素定位失败：没有使用稳定的元素定位方法，导致元素找不到。\n4. 等待时间设置不当：等待时间过短导致元素未加载，过长导致效率低下。\n5. 浏览器驱动版本不匹配：浏览器驱动与浏览器版本不匹配，导致启动失败。\n6. 异常处理不足：没有处理浏览器崩溃、网络错误等情况，导致程序不稳定。', order: 5, duration: '60分钟' },
          { id: 6, course_id: 3, title: '数据存储', content: '数据存储是数据采集的重要环节。在本课时中，我们将详细学习：\n\n1. 数据存储方式：\n   - 文件存储（CSV、JSON、Excel等）\n   - 关系型数据库（MySQL、PostgreSQL等）\n   - NoSQL数据库（MongoDB、Redis等）\n   - 数据仓库\n   - 云存储\n\n2. 文件存储：\n   - CSV文件\n   - JSON文件\n   - Excel文件\n   - 文本文件\n   - 压缩文件\n\n3. 数据库存储：\n   - 数据库连接\n   - 表结构设计\n   - SQL语句\n   - 数据插入和查询\n   - 事务处理\n\n4. 数据存储最佳实践：\n   - 数据备份\n   - 数据压缩\n   - 索引优化\n   - 分区策略\n   - 安全考虑\n\n5. 数据存储的挑战：\n   - 数据量增长\n   - 数据一致性\n   - 性能优化\n   - 可扩展性\n   - 成本控制\n\n通过本课时的学习，您将掌握各种数据存储方式的使用方法，能够根据需求选择合适的存储方案。', pitfalls: '1. 存储方式选择错误：选择了不适合数据类型或规模的存储方式，导致性能问题。\n2. 数据结构设计不当：没有合理设计数据结构，导致数据冗余或查询困难。\n3. 索引使用不当：没有创建合适的索引，导致查询速度慢。\n4. 数据备份不足：没有定期备份数据，导致数据丢失风险。\n5. 安全措施缺失：没有采取适当的安全措施，导致数据泄露风险。\n6. 性能优化不足：没有优化存储性能，导致系统响应慢。', order: 6, duration: '60分钟' },
          { id: 7, course_id: 3, title: '数据清洗概述', content: '数据清洗是数据预处理的重要步骤。在本课时中，我们将详细学习：\n\n1. 数据清洗的基本概念：\n   - 什么是数据清洗\n   - 数据清洗的重要性\n   - 数据清洗的目标\n   - 数据清洗的流程\n\n2. 数据质量评估：\n   - 完整性\n   - 一致性\n   - 准确性\n   - 时效性\n   - 唯一性\n\n3. 数据清洗的方法：\n   - 缺失值处理\n   - 重复值处理\n   - 异常值处理\n   - 数据类型转换\n   - 数据标准化\n\n4. 数据清洗工具：\n   - Pandas\n   - OpenRefine\n   - Excel\n   - SQL\n   - 专业数据清洗工具\n\n5. 数据清洗的挑战：\n   - 数据量过大\n   - 数据格式多样\n   - 业务规则复杂\n   - 清洗效果评估\n   - 时间和资源限制\n\n通过本课时的学习，您将对数据清洗有一个全面的认识，为后续的具体清洗操作打下基础。', pitfalls: '1. 清洗目标不明确：没有明确数据清洗的目标，导致清洗方向混乱。\n2. 过度清洗：过度修改数据，导致数据失真。\n3. 清洗顺序错误：没有按照合理的顺序进行清洗，导致重复工作。\n4. 缺乏业务知识：不了解业务规则，导致清洗结果不符合业务需求。\n5. 清洗效果评估不足：没有评估清洗效果，导致清洗后的数据质量仍然不佳。\n6. 工具使用不当：选择了不适合的清洗工具，影响清洗效率。', order: 7, duration: '60分钟' },
          { id: 8, course_id: 3, title: '处理缺失值', content: '处理缺失值是数据清洗的重要任务。在本课时中，我们将详细学习：\n\n1. 缺失值的类型：\n   - 完全随机缺失\n   - 随机缺失\n   - 非随机缺失\n\n2. 缺失值的识别：\n   - 统计缺失值数量\n   - 缺失值模式分析\n   - 缺失值可视化\n   - 缺失值原因分析\n\n3. 缺失值的处理方法：\n   - 删除法（列表删除、成对删除）\n   - 替换法（均值、中位数、众数替换）\n   - 插值法（线性插值、多项式插值、KNN插值）\n   - 模型法（回归填充、决策树填充）\n   - 多重插补\n\n4. 处理方法的选择：\n   - 基于数据特性\n   - 基于缺失率\n   - 基于业务需求\n   - 基于后续分析方法\n\n5. 缺失值处理的最佳实践：\n   - 记录处理方法\n   - 评估处理效果\n   - 考虑多种方法\n   - 验证处理结果\n\n通过本课时的学习，您将掌握各种缺失值处理方法，能够根据实际情况选择合适的处理策略。', pitfalls: '1. 处理方法选择错误：选择了不适合数据类型或缺失模式的处理方法，导致结果偏差。\n2. 过度删除：删除了过多包含缺失值的记录，导致数据量减少和信息丢失。\n3. 不合理替换：使用了不合理的替换值，导致数据分布失真。\n4. 忽略缺失原因：没有分析缺失值的原因，导致处理方法不当。\n5. 处理效果评估不足：没有评估处理效果，导致处理后的数据质量仍然不佳。\n6. 计算效率低下：使用了计算复杂度高的处理方法，导致处理大型数据集时效率低下。', order: 8, duration: '60分钟' },
          { id: 9, course_id: 3, title: '处理异常值', content: '处理异常值是数据清洗的重要任务。在本课时中，我们将详细学习：\n\n1. 异常值的概念：\n   - 什么是异常值\n   - 异常值的类型\n   - 异常值的影响\n   - 异常值的来源\n\n2. 异常值的检测方法：\n   - 统计方法（Z-score、IQR等）\n   - 可视化方法（箱线图、散点图等）\n   - 机器学习方法（孤立森林、One-class SVM等）\n   - 业务规则方法\n\n3. 异常值的处理方法：\n   - 删除法\n   - 替换法（截断、 Winsorization等）\n   - 分离法\n   - 转换法\n   - 保留法\n\n4. 处理方法的选择：\n   - 基于异常值的性质\n   - 基于数据分布\n   - 基于业务需求\n   - 基于后续分析方法\n\n5. 异常值处理的最佳实践：\n   - 记录处理方法\n   - 评估处理效果\n   - 考虑多种方法\n   - 验证处理结果\n\n通过本课时的学习，您将掌握各种异常值检测和处理方法，能够有效地识别和处理数据中的异常值。', pitfalls: '1. 异常值误判：将正常数据误判为异常值，导致数据丢失。\n2. 检测方法选择错误：选择了不适合数据类型的异常值检测方法，导致检测结果不准确。\n3. 处理方法选择错误：选择了不适合异常值类型的处理方法，导致数据失真。\n4. 忽略异常值的业务意义：没有考虑异常值的业务意义，导致错误处理。\n5. 处理效果评估不足：没有评估处理效果，导致处理后的数据质量仍然不佳。\n6. 计算效率低下：使用了计算复杂度高的检测方法，导致处理大型数据集时效率低下。', order: 9, duration: '60分钟' },
          { id: 10, course_id: 3, title: '数据预处理实战', content: '数据预处理实战是对数据采集与预处理课程内容的综合应用。在本课时中，我们将通过实际案例学习：\n\n1. 案例背景：\n   - 数据采集目标\n   - 数据来源\n   - 数据格式\n   - 分析需求\n\n2. 数据采集实施：\n   - 网络爬虫开发\n   - API数据获取\n   - 数据存储\n   - 数据质量评估\n\n3. 数据清洗流程：\n   - 缺失值处理\n   - 重复值处理\n   - 异常值处理\n   - 数据类型转换\n   - 数据标准化\n\n4. 特征工程：\n   - 特征提取\n   - 特征选择\n   - 特征变换\n   - 特征组合\n\n5. 预处理结果评估：\n   - 数据质量评估\n   - 预处理效果分析\n   - 后续分析准备\n   - 经验总结\n\n通过本课时的学习，您将掌握数据预处理的完整流程，能够独立完成从数据采集到预处理的全过程。', pitfalls: '1. 项目范围过大：选择了过于复杂的项目，导致无法在有限时间内完成。\n2. 数据采集困难：遇到网站反爬、API限制等问题，导致数据采集不完整。\n3. 数据质量差：采集的数据质量差，导致清洗工作量大。\n4. 预处理方法选择不当：选择了不适合数据的预处理方法，导致效果不佳。\n5. 特征工程不足：没有充分进行特征工程，影响后续分析效果。\n6. 文档记录不足：没有详细记录预处理过程，导致后续无法重现。', order: 10, duration: '90分钟' }
        ],
        4: [
          { id: 1, course_id: 4, title: '网络爬虫进阶', content: '网络爬虫进阶是网络爬虫技术的高级课程。在本课时中，我们将详细学习：\n\n1. 爬虫架构设计：\n   - 模块化设计\n   - 任务队列\n   - 调度器\n   - 下载器\n   - 解析器\n\n2. 高级数据提取技术：\n   - 正则表达式高级应用\n   - XPath高级技巧\n   - CSS选择器进阶\n   - JSON数据提取\n   - 动态内容处理\n\n3. 爬虫性能优化：\n   - 并发处理\n   - 缓存机制\n   - 批量请求\n   - 数据压缩\n   - 内存管理\n\n4. 爬虫监控与维护：\n   - 日志记录\n   - 错误处理\n   - 断点续爬\n   - 状态监控\n   - 自动重试\n\n5. 爬虫的法律与伦理：\n   - 数据采集合法性\n   -  robots.txt协议详解\n   - 网站使用条款\n   - 数据使用限制\n   - 伦理考量\n\n通过本课时的学习，您将掌握网络爬虫的高级技术和策略，能够开发更加高效、稳定的爬虫系统。', pitfalls: '1. 架构设计过于复杂：设计了过于复杂的爬虫架构，导致维护困难。\n2. 性能优化过度：过度优化性能，导致代码可读性差。\n3. 法律意识淡薄：在采集数据时没有考虑法律法规，可能导致法律风险。\n4. 监控不足：没有充分监控爬虫运行状态，导致问题无法及时发现。\n5. 错误处理不完善：没有处理各种异常情况，导致爬虫不稳定。\n6. 数据质量忽视：只关注采集速度，忽视了数据质量。', order: 1, duration: '45分钟' },
          { id: 2, course_id: 4, title: '反爬策略应对', content: '反爬策略应对是网络爬虫开发中的重要挑战。在本课时中，我们将详细学习：\n\n1. 常见反爬措施：\n   - User-Agent检测\n   - IP限制\n   - 验证码\n   - 动态加载\n   - 登录验证\n   - 蜜罐陷阱\n   - 行为分析\n\n2. User-Agent应对：\n   - 随机User-Agent\n   - 浏览器指纹模拟\n   - 请求头优化\n\n3. IP限制应对：\n   - 代理IP池\n   - 代理轮换策略\n   - IP质量评估\n   - 分布式爬虫\n\n4. 验证码处理：\n   - 手动识别\n   - OCR技术\n   - 第三方验证码服务\n   - 验证码绕过技巧\n\n5. 动态内容处理：\n   - Selenium\n   - Pyppeteer\n   - 逆向工程\n   - API分析\n\n6. 登录验证处理：\n   - 自动登录\n   - Cookie管理\n   - Session维护\n   - 验证码处理\n\n通过本课时的学习，您将掌握各种反爬策略的应对方法，能够有效地绕过网站的反爬措施。', pitfalls: '1. 反爬措施过度：采取过于激进的反爬措施，可能导致网站负担过重。\n2. 代理IP质量差：使用了质量差的代理IP，导致请求失败率高。\n3. 验证码处理成本高：验证码处理成本过高，影响爬虫效率。\n4. 行为模拟不自然：行为模拟不自然，容易被网站识别。\n5. 法律风险：采取的反爬措施可能违反法律法规。\n6. 维护成本高：反爬策略需要不断更新，维护成本高。', order: 2, duration: '60分钟' },
          { id: 3, course_id: 4, title: '异步爬虫', content: '异步爬虫是提高爬虫效率的重要技术。在本课时中，我们将详细学习：\n\n1. 异步编程基础：\n   - 同步与异步的区别\n   - 事件循环\n   - 协程\n   - 回调函数\n\n2. asyncio库使用：\n   - 基本概念\n   - 异步函数定义\n   - await关键字\n   - 任务管理\n   - 事件循环操作\n\n3. aiohttp库使用：\n   - 异步HTTP请求\n   - 会话管理\n   - 请求参数设置\n   - 响应处理\n   - 并发控制\n\n4. 异步爬虫设计：\n   - 任务队列\n   - 并发限制\n   - 错误处理\n   - 重试机制\n   - 进度监控\n\n5. 性能优化：\n   - 并发数调优\n   - 内存使用优化\n   - 网络延迟处理\n   - 数据处理优化\n\n通过本课时的学习，您将掌握异步爬虫的开发方法，能够大幅提高爬虫的采集效率。', pitfalls: '1. 并发数设置过高：并发数设置过高，导致被网站限制或系统资源不足。\n2. 错误处理复杂：异步代码的错误处理比同步代码更复杂，容易遗漏。\n3. 调试困难：异步代码的调试比同步代码更困难，难以定位问题。\n4. 内存泄漏：异步操作可能导致内存泄漏，特别是在长时间运行的爬虫中。\n5. 依赖管理复杂：异步爬虫依赖的库版本兼容性问题较多。\n6. 代码可读性差：异步代码的可读性比同步代码差，维护困难。', order: 3, duration: '60分钟' },
          { id: 4, course_id: 4, title: '分布式爬虫', content: '分布式爬虫是处理大规模数据采集的重要技术。在本课时中，我们将详细学习：\n\n1. 分布式爬虫架构：\n   - 主从架构\n   - 对等架构\n   - 任务分配策略\n   - 数据同步机制\n\n2. 消息队列：\n   - RabbitMQ\n   - Redis\n   - Kafka\n   - 消息格式设计\n   - 消息处理流程\n\n3. 分布式存储：\n   - 共享数据库\n   - 分布式文件系统\n   - 数据分片策略\n   - 一致性保证\n\n4. 任务调度：\n   - 任务队列管理\n   - 负载均衡\n   - 故障恢复\n   - 任务优先级\n\n5. 监控与管理：\n   - 节点状态监控\n   - 任务进度跟踪\n   - 系统健康检查\n   - 日志聚合\n\n通过本课时的学习，您将掌握分布式爬虫的设计和实现方法，能够处理大规模的数据采集任务。', pitfalls: '1. 架构设计复杂：分布式爬虫的架构设计比单机爬虫复杂得多。\n2. 部署成本高：分布式爬虫需要多台服务器，部署成本高。\n3. 数据一致性问题：分布式环境下的数据一致性难以保证。\n4. 网络延迟：网络延迟可能影响分布式爬虫的性能。\n5. 故障处理复杂：分布式系统的故障处理比单机系统复杂。\n6. 调试困难：分布式系统的调试比单机系统困难。', order: 4, duration: '60分钟' },
          { id: 5, course_id: 4, title: 'API数据采集', content: 'API数据采集是获取结构化数据的重要方法。在本课时中，我们将详细学习：\n\n1. API基础：\n   - RESTful API\n   - GraphQL API\n   - API认证方式\n   - API文档阅读\n\n2. API请求：\n   - 请求方法\n   - 请求参数\n   - 请求头\n   - 响应格式\n   - 错误处理\n\n3. API认证：\n   - API Key\n   - OAuth\n   - JWT\n   - 令牌管理\n\n4. API速率限制：\n   - 限制类型\n   - 应对策略\n   - 缓存机制\n   - 重试策略\n\n5. 批量数据获取：\n   - 分页处理\n   - 批量请求\n   - 数据去重\n   - 增量更新\n\n6. API数据处理：\n   - JSON解析\n   - 数据转换\n   - 数据验证\n   - 数据存储\n\n通过本课时的学习，您将掌握API数据采集的方法，能够高效地获取和处理API数据。', pitfalls: '1. 认证失败：API认证方式错误或令牌过期，导致请求失败。\n2. 速率限制：没有处理API速率限制，导致请求被拒绝。\n3. 分页处理不当：没有正确处理API分页，导致数据获取不完整。\n4. 错误处理不足：没有处理API错误响应，导致程序崩溃。\n5. 数据验证不足：没有验证API返回的数据，导致数据质量问题。\n6. 文档理解错误：没有正确理解API文档，导致请求参数错误。', order: 5, duration: '60分钟' },
          { id: 6, course_id: 4, title: '爬虫项目设计', content: '爬虫项目设计是确保爬虫项目成功的重要步骤。在本课时中，我们将详细学习：\n\n1. 项目需求分析：\n   - 目标数据定义\n   - 采集范围确定\n   - 数据质量要求\n   - 时间和资源限制\n\n2. 技术方案设计：\n   - 爬虫架构选择\n   - 技术栈确定\n   - 存储方案设计\n   - 监控方案设计\n\n3. 网站分析：\n   - 结构分析\n   - 反爬措施分析\n   - 数据结构分析\n   - API分析\n\n4. 爬虫开发计划：\n   - 任务分解\n   - 时间线规划\n   - 里程碑设定\n   - 风险评估\n\n5. 测试策略：\n   - 单元测试\n   - 集成测试\n   - 性能测试\n   - 稳定性测试\n\n6. 部署与维护：\n   - 部署方案\n   - 监控设置\n   - 日志管理\n   - 维护计划\n\n通过本课时的学习，您将掌握爬虫项目的设计方法，能够制定科学合理的爬虫开发计划。', pitfalls: '1. 需求分析不充分：没有充分分析项目需求，导致开发过程中频繁变更。\n2. 技术方案选择错误：选择了不适合项目需求的技术方案，导致开发困难。\n3. 网站分析不足：没有充分分析目标网站，导致开发过程中遇到意外问题。\n4. 计划制定不合理：制定了不合理的开发计划，导致项目延期。\n5. 测试覆盖不足：测试覆盖不足，导致上线后出现问题。\n6. 部署方案不当：部署方案不当，导致爬虫运行不稳定。', order: 6, duration: '60分钟' },
          { id: 7, course_id: 4, title: '爬虫实战案例', content: '爬虫实战案例是对网络爬虫技术的综合应用。在本课时中，我们将通过实际案例学习：\n\n1. 案例背景：\n   - 数据采集目标\n   - 目标网站分析\n   - 技术挑战\n   - 预期成果\n\n2. 爬虫设计：\n   - 架构设计\n   - 技术选型\n   - 流程设计\n   - 数据模型\n\n3. 爬虫实现：\n   - 代码结构\n   - 核心功能实现\n   - 反爬措施应对\n   - 错误处理\n\n4. 数据处理：\n   - 数据提取\n   - 数据清洗\n   - 数据存储\n   - 数据质量评估\n\n5. 性能优化：\n   - 并发处理\n   - 缓存机制\n   - 内存使用优化\n   - 网络请求优化\n\n6. 部署与监控：\n   - 部署方案\n   - 监控设置\n   - 日志管理\n   - 故障处理\n\n通过本课时的学习，您将掌握实际爬虫项目的开发方法，能够独立完成复杂的爬虫项目。', pitfalls: '1. 项目范围过大：选择了过于复杂的项目，导致无法在有限时间内完成。\n2. 反爬措施应对不足：没有充分应对网站的反爬措施，导致爬虫被封禁。\n3. 数据质量差：采集的数据质量差，导致后续分析困难。\n4. 性能优化不足：爬虫性能不足，导致采集速度慢。\n5. 错误处理不完善：没有充分处理各种异常情况，导致爬虫不稳定。\n6. 文档记录不足：没有详细记录项目开发过程，导致后续维护困难。', order: 7, duration: '60分钟' },
          { id: 8, course_id: 4, title: '爬虫项目总结', content: '爬虫项目总结是对爬虫开发经验的回顾和总结。在本课时中，我们将详细学习：\n\n1. 项目回顾：\n   - 项目目标达成情况\n   - 技术实现总结\n   - 遇到的挑战\n   - 解决方案\n\n2. 经验教训：\n   - 技术选择\n   - 架构设计\n   - 开发流程\n   - 测试策略\n   - 部署维护\n\n3. 最佳实践：\n   - 爬虫开发规范\n   - 代码质量\n   - 性能优化\n   - 错误处理\n   - 监控管理\n\n4. 行业趋势：\n   - 爬虫技术发展\n   - 反爬技术演变\n   - 法律法规变化\n   - 工具和框架更新\n\n5. 未来展望：\n   - 技术改进方向\n   - 应用场景拓展\n   - 自动化和智能化\n   - 合规性提升\n\n6. 学习资源：\n   - 书籍推荐\n   - 在线课程\n   - 社区和论坛\n   - 工具和框架\n\n通过本课时的学习，您将总结爬虫项目的经验教训，为未来的爬虫开发提供参考。', pitfalls: '1. 总结不全面：没有全面总结项目经验和教训，导致无法为未来项目提供参考。\n2. 经验教训分析不深入：对经验教训的分析不够深入，无法从中学习。\n3. 最佳实践提炼不足：没有提炼出有价值的最佳实践，影响后续项目。\n4. 行业趋势把握不准确：对行业趋势的把握不准确，导致技术选型落后。\n5. 未来规划不实际：未来规划过于理想化，无法实现。\n6. 学习资源推荐不实用：推荐的学习资源不实用，对后续学习帮助不大。', order: 8, duration: '60分钟' }
        ],
        5: [
          { id: 1, course_id: 5, title: '数据质量评估', content: '数据质量评估是数据预处理的第一步。在本课时中，我们将详细学习：\n\n1. 数据质量的维度：\n   - 完整性\n   - 一致性\n   - 准确性\n   - 时效性\n   - 唯一性\n   - 有效性\n\n2. 数据质量评估方法：\n   - 统计分析\n   - 可视化分析\n   - 规则检查\n   - 数据 profiling\n\n3. 数据质量评估工具：\n   - Pandas\n   - Great Expectations\n   - Data Quality Frameworks\n   - 自定义脚本\n\n4. 数据质量报告：\n   - 报告内容设计\n   - 可视化展示\n   - 问题优先级排序\n   - 改进建议\n\n5. 数据质量监控：\n   - 实时监控\n   - 定期评估\n   - 异常检测\n   - 告警机制\n\n通过本课时的学习，您将掌握数据质量评估的方法和工具，能够全面评估数据质量并制定改进计划。', pitfalls: '1. 评估维度不全面：只评估了部分数据质量维度，导致评估结果不完整。\n2. 评估方法选择错误：选择了不适合数据类型的评估方法，导致评估结果不准确。\n3. 工具使用不当：使用了不适合的评估工具，影响评估效率和结果。\n4. 报告设计不合理：报告设计不合理，导致问题不突出，难以理解。\n5. 监控机制缺失：没有建立数据质量监控机制，导致数据质量问题无法及时发现。\n6. 改进措施不具体：提出的改进措施不具体，无法有效解决数据质量问题。', order: 1, duration: '45分钟' },
          { id: 2, course_id: 5, title: '缺失值处理方法', content: '缺失值处理是数据预处理的重要任务。在本课时中，我们将详细学习：\n\n1. 缺失值的类型：\n   - 完全随机缺失 (MCAR)\n   - 随机缺失 (MAR)\n   - 非随机缺失 (MNAR)\n\n2. 缺失值的识别：\n   - 统计缺失值数量\n   - 缺失值模式分析\n   - 缺失值可视化\n   - 缺失值原因分析\n\n3. 缺失值处理方法：\n   - 删除法（列表删除、成对删除、删除变量）\n   - 替换法（均值、中位数、众数、常数替换）\n   - 插值法（线性插值、多项式插值、KNN插值）\n   - 模型法（回归填充、决策树填充、多重插补）\n\n4. 处理方法的选择：\n   - 基于数据特性\n   - 基于缺失率\n   - 基于业务需求\n   - 基于后续分析方法\n\n5. 缺失值处理的最佳实践：\n   - 记录处理方法\n   - 评估处理效果\n   - 考虑多种方法\n   - 验证处理结果\n\n通过本课时的学习，您将掌握各种缺失值处理方法，能够根据实际情况选择合适的处理策略。', pitfalls: '1. 处理方法选择错误：选择了不适合数据类型或缺失模式的处理方法，导致结果偏差。\n2. 过度删除：删除了过多包含缺失值的记录，导致数据量减少和信息丢失。\n3. 不合理替换：使用了不合理的替换值，导致数据分布失真。\n4. 忽略缺失原因：没有分析缺失值的原因，导致处理方法不当。\n5. 处理效果评估不足：没有评估处理效果，导致处理后的数据质量仍然不佳。\n6. 计算效率低下：使用了计算复杂度高的处理方法，导致处理大型数据集时效率低下。', order: 2, duration: '60分钟' },
          { id: 3, course_id: 5, title: '异常值检测与处理', content: '异常值检测与处理是数据预处理的重要任务。在本课时中，我们将详细学习：\n\n1. 异常值的概念：\n   - 什么是异常值\n   - 异常值的类型（全局异常值、上下文异常值、集体异常值）\n   - 异常值的影响\n   - 异常值的来源\n\n2. 异常值的检测方法：\n   - 统计方法（Z-score、IQR、DBSCAN等）\n   - 可视化方法（箱线图、散点图、热力图等）\n   - 机器学习方法（孤立森林、One-class SVM、LOF等）\n   - 业务规则方法\n\n3. 异常值的处理方法：\n   - 删除法\n   - 替换法（截断、Winsorization等）\n   - 分离法\n   - 转换法\n   - 保留法\n\n4. 处理方法的选择：\n   - 基于异常值的性质\n   - 基于数据分布\n   - 基于业务需求\n   - 基于后续分析方法\n\n5. 异常值处理的最佳实践：\n   - 记录处理方法\n   - 评估处理效果\n   - 考虑多种方法\n   - 验证处理结果\n\n通过本课时的学习，您将掌握各种异常值检测和处理方法，能够有效地识别和处理数据中的异常值。', pitfalls: '1. 异常值误判：将正常数据误判为异常值，导致数据丢失。\n2. 检测方法选择错误：选择了不适合数据类型的异常值检测方法，导致检测结果不准确。\n3. 处理方法选择错误：选择了不适合异常值类型的处理方法，导致数据失真。\n4. 忽略异常值的业务意义：没有考虑异常值的业务意义，导致错误处理。\n5. 处理效果评估不足：没有评估处理效果，导致处理后的数据质量仍然不佳。\n6. 计算效率低下：使用了计算复杂度高的检测方法，导致处理大型数据集时效率低下。', order: 3, duration: '60分钟' },
          { id: 4, course_id: 5, title: '重复数据处理', content: '重复数据处理是数据预处理的重要任务。在本课时中，我们将详细学习：\n\n1. 重复数据的类型：\n   - 完全重复\n   - 部分重复\n   - 近似重复\n\n2. 重复数据的识别：\n   - 完全重复检测\n   - 部分重复检测\n   - 近似重复检测（模糊匹配）\n   - 重复数据可视化\n\n3. 重复数据的处理方法：\n   - 删除重复项\n   - 合并重复项\n   - 标记重复项\n   - 基于规则处理\n\n4. 重复数据处理的工具：\n   - Pandas\n   - fuzzywuzzy\n   - dedupe\n   - 自定义算法\n\n5. 重复数据处理的最佳实践：\n   - 确定重复定义\n   - 选择合适的检测方法\n   - 建立处理规则\n   - 验证处理结果\n   - 防止重复数据产生\n\n通过本课时的学习，您将掌握重复数据检测和处理的方法，能够有效地识别和处理数据中的重复项。', pitfalls: '1. 重复定义不明确：没有明确什么是重复数据，导致处理结果不符合预期。\n2. 检测方法选择错误：选择了不适合数据类型的重复检测方法，导致检测结果不准确。\n3. 处理方法选择错误：选择了不适合重复类型的处理方法，导致数据丢失或失真。\n4. 近似重复处理困难：近似重复数据的处理比完全重复数据更困难，容易出现误判。\n5. 处理效果评估不足：没有评估处理效果，导致处理后的数据仍有重复。\n6. 性能问题：处理大型数据集时，重复检测可能会遇到性能瓶颈。', order: 4, duration: '60分钟' },
          { id: 5, course_id: 5, title: '数据类型转换', content: '数据类型转换是数据预处理的基础任务。在本课时中，我们将详细学习：\n\n1. 常见数据类型：\n   - 数值类型（整数、浮点数）\n   - 字符串类型\n   - 日期时间类型\n   - 布尔类型\n   - 分类类型\n\n2. 数据类型转换方法：\n   - 显式转换\n   - 隐式转换\n   - 函数转换\n   - 自定义转换\n\n3. 特殊类型转换：\n   - 字符串转日期时间\n   - 数值转分类\n   - 分类转数值\n   - 文本编码\n\n4. 数据类型转换的挑战：\n   - 格式不一致\n   - 缺失值处理\n   - 错误值处理\n   - 性能优化\n\n5. 数据类型转换的最佳实践：\n   - 理解数据含义\n   - 选择合适的目标类型\n   - 处理转换错误\n   - 验证转换结果\n   - 记录转换过程\n\n通过本课时的学习，您将掌握各种数据类型转换的方法，能够正确地转换数据类型以满足分析需求。', pitfalls: '1. 转换目标类型选择错误：选择了不适合数据的目标类型，导致数据丢失或失真。\n2. 格式处理不当：没有正确处理数据格式，导致转换失败。\n3. 错误处理不足：没有处理转换过程中的错误，导致程序崩溃。\n4. 性能优化不足：转换大型数据集时，没有优化转换过程，导致效率低下。\n5. 验证不足：没有验证转换结果，导致转换错误未被发现。\n6. 内存使用过高：转换过程中内存使用过高，导致系统资源不足。', order: 5, duration: '60分钟' },
          { id: 6, course_id: 5, title: '数据标准化', content: '数据标准化是数据预处理的重要步骤。在本课时中，我们将详细学习：\n\n1. 数据标准化的概念：\n   - 什么是数据标准化\n   - 数据标准化的重要性\n   - 数据标准化的应用场景\n\n2. 常见标准化方法：\n   - 最小-最大标准化（Min-Max Scaling）\n   - 标准差标准化（Standard Scaling）\n   - 稳健标准化（Robust Scaling）\n   - 归一化（Normalization）\n   - 二值化（Binarization）\n\n3. 标准化方法的选择：\n   - 基于数据分布\n   - 基于算法要求\n   - 基于业务需求\n   - 基于计算效率\n\n4. 标准化的实现：\n   - 使用Scikit-learn\n   - 使用Pandas\n   - 自定义实现\n\n5. 标准化的最佳实践：\n   - 在训练集上拟合，在测试集上应用\n   - 保存标准化参数\n   - 处理新数据\n   - 评估标准化效果\n\n通过本课时的学习，您将掌握各种数据标准化方法，能够根据数据特点和分析需求选择合适的标准化方法。', pitfalls: '1. 标准化方法选择错误：选择了不适合数据分布或算法要求的标准化方法，导致效果不佳。\n2. 训练集和测试集处理不一致：在训练集和测试集上使用不同的标准化参数，导致模型性能下降。\n3. 标准化参数未保存：没有保存标准化参数，导致无法处理新数据。\n4. 异常值影响：标准化过程受到异常值的影响，导致结果不准确。\n5. 过度标准化：对不需要标准化的数据进行标准化，导致信息丢失。\n6. 计算效率低下：使用了计算复杂度高的标准化方法，导致处理大型数据集时效率低下。', order: 6, duration: '60分钟' },
          { id: 7, course_id: 5, title: '特征工程基础', content: '特征工程是数据分析和机器学习的重要环节。在本课时中，我们将详细学习：\n\n1. 特征工程的概念：\n   - 什么是特征工程\n   - 特征工程的重要性\n   - 特征工程的流程\n\n2. 特征类型：\n   - 数值特征\n   - 分类特征\n   - 文本特征\n   - 时间特征\n   - 空间特征\n\n3. 特征提取：\n   - 原始特征提取\n   - 派生特征创建\n   - 交互特征\n   - 聚合特征\n\n4. 特征选择：\n   - 过滤法（Filter）\n   - 包装法（Wrapper）\n   - 嵌入法（Embedded）\n   - 特征重要性评估\n\n5. 特征变换：\n   - 数值变换（对数、平方根等）\n   - 分类编码（独热编码、标签编码等）\n   - 降维（PCA、t-SNE等）\n   - 特征离散化\n\n6. 特征工程的最佳实践：\n   - 理解业务需求\n   - 结合领域知识\n   - 迭代优化\n   - 验证特征效果\n   - 文档记录\n\n通过本课时的学习，您将掌握特征工程的基本概念和方法，能够为数据分析和机器学习任务创建有效的特征。', pitfalls: '1. 特征提取不足：没有充分提取有价值的特征，导致模型性能不佳。\n2. 特征选择不当：选择了无关或冗余的特征，导致模型过拟合或性能下降。\n3. 特征变换错误：使用了不适合特征类型的变换方法，导致信息丢失。\n4. 领域知识缺失：没有结合领域知识进行特征工程，导致特征不具有业务意义。\n5. 过拟合风险：创建了过多的特征，导致模型过拟合。\n6. 计算效率低下：特征工程过程计算效率低下，导致处理大型数据集时困难。', order: 7, duration: '60分钟' },
          { id: 8, course_id: 5, title: '文本数据处理', content: '文本数据处理是特征工程的重要组成部分。在本课时中，我们将详细学习：\n\n1. 文本数据的特点：\n   - 非结构化\n   - 高维\n   - 噪声多\n   - 语义丰富\n\n2. 文本预处理：\n   - 分词\n   - 停用词移除\n   - 词干提取\n   - 词形还原\n   - 拼写纠错\n\n3. 文本特征提取：\n   - 词袋模型（Bag of Words）\n   - TF-IDF\n   - n-gram\n   - 词嵌入（Word Embedding）\n   - 主题模型（LDA、NMF等）\n\n4. 文本分类特征：\n   - 文本长度\n   - 词汇多样性\n   - 情感分析\n   - 关键词提取\n   - 命名实体识别\n\n5. 文本处理工具：\n   - NLTK\n   - spaCy\n   - jieba（中文分词）\n   - scikit-learn\n   - transformers\n\n6. 文本处理的最佳实践：\n   - 理解文本 domain\n   - 选择合适的预处理步骤\n   - 选择合适的特征提取方法\n   - 验证特征效果\n   - 处理不平衡数据\n\n通过本课时的学习，您将掌握文本数据处理的方法和工具，能够从文本数据中提取有价值的特征。', pitfalls: '1. 预处理过度：过度预处理导致文本信息丢失。\n2. 特征提取方法选择错误：选择了不适合任务的特征提取方法，导致效果不佳。\n3. 维度灾难：文本特征维度过高，导致计算效率低下和过拟合。\n4. 领域适应性差：使用了通用的文本处理方法，没有考虑特定领域的特点。\n5. 多语言处理困难：处理多语言文本时，没有考虑语言差异。\n6. 计算资源消耗：文本处理，特别是深度学习方法，可能消耗大量计算资源。', order: 8, duration: '60分钟' },
          { id: 9, course_id: 5, title: '时间序列数据处理', content: '时间序列数据处理是数据分析的重要领域。在本课时中，我们将详细学习：\n\n1. 时间序列的特点：\n   - 时间依赖性\n   - 趋势\n   - 季节性\n   - 周期性\n   - 噪声\n\n2. 时间序列预处理：\n   - 时间格式处理\n   - 缺失值处理\n   - 异常值检测\n   - 重采样\n   - 平滑\n\n3. 时间序列特征提取：\n   - 基本统计特征\n   - 滞后特征\n   - 滚动统计特征\n   - 季节性特征\n   - 趋势特征\n\n4. 时间序列变换：\n   - 差分变换\n   - 对数变换\n   - 标准化\n   - Box-Cox变换\n\n5. 时间序列分析工具：\n   - Pandas\n   - statsmodels\n   - Prophet\n   - scikit-learn\n   - PyTorch/TensorFlow\n\n6. 时间序列处理的最佳实践：\n   - 理解时间序列特性\n   - 选择合适的预处理方法\n   - 提取有意义的特征\n   - 验证特征效果\n   - 考虑业务上下文\n\n通过本课时的学习，您将掌握时间序列数据处理的方法和工具，能够从时间序列数据中提取有价值的特征。', pitfalls: '1. 时间格式处理错误：没有正确处理时间格式，导致时间序列分析错误。\n2. 预处理不当：预处理方法选择不当，导致时间序列特性被破坏。\n3. 特征提取不足：没有充分提取时间序列的特征，导致分析效果不佳。\n4. 过拟合风险：提取了过多的时间特征，导致模型过拟合。\n5. 季节性处理不当：没有正确处理时间序列的季节性，导致分析结果偏差。\n6. 计算效率低下：时间序列处理，特别是滚动统计，可能计算效率低下。', order: 9, duration: '60分钟' },
          { id: 10, course_id: 5, title: '数据预处理管道', content: '数据预处理管道是自动化数据预处理流程的重要工具。在本课时中，我们将详细学习：\n\n1. 预处理管道的概念：\n   - 什么是预处理管道\n   - 预处理管道的优势\n   - 预处理管道的应用场景\n\n2. 预处理管道的组成：\n   - 数据读取\n   - 数据清洗\n   - 特征工程\n   - 特征选择\n   - 数据标准化\n\n3. 预处理管道的实现：\n   - 使用scikit-learn的Pipeline\n   - 使用scikit-learn的ColumnTransformer\n   - 自定义管道\n   - 并行处理\n\n4. 预处理管道的优化：\n   - 内存使用优化\n   - 计算效率优化\n   - 错误处理\n   - 日志记录\n\n5. 预处理管道的部署：\n   - 模型序列化\n   - 管道保存和加载\n   - 在线预测\n   - 批处理\n\n6. 预处理管道的最佳实践：\n   - 模块化设计\n   - 可重现性\n   - 版本控制\n   - 测试和验证\n   - 文档记录\n\n通过本课时的学习，您将掌握数据预处理管道的设计和实现方法，能够构建高效、可维护的预处理流程。', pitfalls: '1. 管道设计过于复杂：设计了过于复杂的预处理管道，导致维护困难。\n2. 错误处理不足：没有充分处理管道中的错误，导致运行不稳定。\n3. 性能优化不足：管道运行效率低下，特别是处理大型数据集时。\n4. 可重现性差：管道缺乏可重现性，导致结果不一致。\n5. 部署困难：管道部署困难，无法在生产环境中使用。\n6. 测试覆盖不足：管道测试覆盖不足，导致上线后出现问题。', order: 10, duration: '60分钟' },
          { id: 11, course_id: 5, title: '预处理实战案例', content: '预处理实战案例是对数据预处理技术的综合应用。在本课时中，我们将通过实际案例学习：\n\n1. 案例背景：\n   - 数据来源和特点\n   - 分析目标\n   - 数据质量评估\n   - 预处理需求\n\n2. 数据预处理流程：\n   - 数据读取和初步分析\n   - 数据清洗（缺失值、异常值、重复值处理）\n   - 特征工程（特征提取、选择、变换）\n   - 数据标准化\n   - 预处理管道构建\n\n3. 预处理工具使用：\n   - Pandas\n   - scikit-learn\n   - 自定义脚本\n   - 可视化工具\n\n4. 预处理效果评估：\n   - 数据质量改善\n   - 特征有效性\n   - 模型性能提升\n   - 计算效率\n\n5. 经验总结：\n   - 成功经验\n   - 遇到的挑战\n   - 解决方案\n   - 改进建议\n\n通过本课时的学习，您将掌握实际数据预处理项目的实施方法，能够独立完成从数据读取到预处理的全过程。', pitfalls: '1. 项目范围过大：选择了过于复杂的项目，导致无法在有限时间内完成。\n2. 数据质量差：原始数据质量差，导致预处理工作量大。\n3. 预处理方法选择不当：选择了不适合数据的预处理方法，导致效果不佳。\n4. 特征工程不足：没有充分进行特征工程，影响后续分析效果。\n5. 管道设计不合理：预处理管道设计不合理，导致运行效率低下。\n6. 文档记录不足：没有详细记录预处理过程，导致后续无法重现。', order: 11, duration: '60分钟' },
          { id: 12, course_id: 5, title: '预处理项目总结', content: '预处理项目总结是对数据预处理经验的回顾和总结。在本课时中，我们将详细学习：\n\n1. 项目回顾：\n   - 项目目标达成情况\n   - 技术实现总结\n   - 遇到的挑战\n   - 解决方案\n\n2. 经验教训：\n   - 数据质量评估\n   - 预处理方法选择\n   - 特征工程\n   - 管道设计\n   - 性能优化\n\n3. 最佳实践：\n   - 预处理流程标准化\n   - 工具选择\n   - 错误处理\n   - 文档记录\n   - 团队协作\n\n4. 行业趋势：\n   - 自动化预处理\n   - 机器学习辅助预处理\n   - 实时预处理\n   - 预处理工具发展\n\n5. 未来展望：\n   - 技术改进方向\n   - 应用场景拓展\n   - 与其他技术的融合\n   - 标准化和规范化\n\n6. 学习资源：\n   - 书籍推荐\n   - 在线课程\n   - 工具和库\n   - 社区和论坛\n\n通过本课时的学习，您将总结数据预处理项目的经验教训，为未来的预处理项目提供参考。', pitfalls: '1. 总结不全面：没有全面总结项目经验和教训，导致无法为未来项目提供参考。\n2. 经验教训分析不深入：对经验教训的分析不够深入，无法从中学习。\n3. 最佳实践提炼不足：没有提炼出有价值的最佳实践，影响后续项目。\n4. 行业趋势把握不准确：对行业趋势的把握不准确，导致技术选型落后。\n5. 未来规划不实际：未来规划过于理想化，无法实现。\n6. 学习资源推荐不实用：推荐的学习资源不实用，对后续学习帮助不大。', order: 12, duration: '60分钟' }
        ],
        6: [
          { id: 1, course_id: 6, title: 'Pandas进阶', content: 'Pandas进阶是Pandas库的高级应用课程。在本课时中，我们将详细学习：\n\n1. Pandas库简介：\n   - Pandas的优势和特点\n   - 版本特性\n   - 安装和导入\n   - 与其他库的集成\n\n2. 数据结构进阶：\n   - Series高级操作\n   - DataFrame高级操作\n   - 索引对象\n   - 多级索引\n\n3. 数据类型处理：\n   - 分类数据类型\n   - 日期时间类型\n   - 时间间隔类型\n   - 自定义数据类型\n\n4. 高级功能介绍：\n   - 向量化操作\n   - 函数应用\n   - 方法链\n   - 管道操作\n\n5. 性能考量：\n   - 内存使用优化\n   - 计算效率提升\n   - 大数据处理\n   - 并行计算\n\n通过本课时的学习，您将对Pandas库有更深入的了解，为后续的高级操作打下基础。', pitfalls: '1. 版本兼容性问题：不同版本的Pandas可能有不同的API，导致代码不兼容。\n2. 内存使用过高：处理大型数据集时，Pandas可能会消耗大量内存。\n3. 性能瓶颈：某些操作在大型数据集上可能性能较差。\n4. 方法选择不当：选择了不适合任务的Pandas方法，导致效率低下。\n5. 索引使用不当：没有充分利用索引，导致查询速度慢。\n6. 错误处理不足：没有处理Pandas操作中可能出现的错误。', order: 1, duration: '45分钟' },
          { id: 2, course_id: 6, title: '数据索引与选择', content: '数据索引与选择是Pandas的核心功能。在本课时中，我们将详细学习：\n\n1. 索引类型：\n   - 整数索引\n   - 标签索引\n   - 布尔索引\n   - 多级索引\n\n2. 基本索引操作：\n   - .loc[] 标签索引\n   - .iloc[] 位置索引\n   - .ix[] 混合索引（已废弃）\n   - [] 操作符\n\n3. 高级索引技巧：\n   - 布尔掩码\n   - 花式索引\n   - 切片操作\n   - 条件选择\n\n4. 索引优化：\n   - 索引类型选择\n   - 索引排序\n   - 索引重建\n   - 索引设置\n\n5. 实战应用：\n   - 数据筛选\n   - 数据子集选择\n   - 条件查询\n   - 复杂索引组合\n\n通过本课时的学习，您将掌握Pandas的高级索引和选择技巧，能够高效地获取和操作数据。', pitfalls: '1. 索引类型混淆：混淆了标签索引和位置索引，导致选择错误的数据。\n2. 链式赋值警告：使用链式操作修改数据时出现警告。\n3. 性能问题：大型数据集上的索引操作可能性能较差。\n4. 内存使用：某些索引操作可能会创建数据的副本，增加内存使用。\n5. 多级索引复杂性：多级索引的操作较为复杂，容易出错。\n6. 索引对齐：Pandas的索引对齐特性可能导致意外的结果。', order: 2, duration: '60分钟' },
          { id: 3, course_id: 6, title: '数据合并与连接', content: '数据合并与连接是Pandas的重要功能。在本课时中，我们将详细学习：\n\n1. 合并类型：\n   - 内连接（inner join）\n   - 外连接（outer join）\n   - 左连接（left join）\n   - 右连接（right join）\n\n2. 合并方法：\n   - merge() 函数\n   - join() 方法\n   - concat() 函数\n   - append() 方法\n\n3. 合并参数：\n   - on 参数\n   - how 参数\n   - left_on/right_on 参数\n   - left_index/right_index 参数\n   - suffixes 参数\n\n4. 高级合并技巧：\n   - 多键合并\n   - 合并不同列名的数据\n   - 合并索引和列\n   - 处理重复键\n\n5. 性能优化：\n   - 索引优化\n   - 内存使用\n   - 大型数据合并\n   - 并行处理\n\n通过本课时的学习，您将掌握Pandas的数据合并和连接技巧，能够有效地整合不同来源的数据。', pitfalls: '1. 合并键选择错误：选择了不唯一或不匹配的键进行合并，导致结果不符合预期。\n2. 内存不足：合并大型数据集时可能出现内存不足的问题。\n3. 性能问题：合并操作在大型数据集上可能性能较差。\n4. 重复列名：合并后出现重复列名，导致后续操作困难。\n5. 索引混乱：合并后索引可能变得混乱，需要重新整理。\n6. 数据类型不匹配：合并时数据类型不匹配，导致错误。', order: 3, duration: '60分钟' },
          { id: 4, course_id: 6, title: '数据分组与聚合', content: '数据分组与聚合是Pandas的强大功能。在本课时中，我们将详细学习：\n\n1. 分组操作：\n   - groupby() 函数\n   - 分组键类型\n   - 多级分组\n   - 分组对象操作\n\n2. 聚合函数：\n   - 内置聚合函数（sum, mean, count等）\n   - 自定义聚合函数\n   - 多聚合函数应用\n   - 命名聚合\n\n3. 分组转换：\n   - transform() 方法\n   - apply() 方法\n   - 窗口函数\n   - 分组过滤\n\n4. 高级分组技巧：\n   - 按时间分组\n   - 按条件分组\n   - 分组后的数据处理\n   - 分组结果可视化\n\n5. 性能优化：\n   - 分组键选择\n   - 聚合函数选择\n   - 内存使用\n   - 大型数据分组\n\n通过本课时的学习，您将掌握Pandas的分组和聚合技巧，能够高效地对数据进行汇总和分析。', pitfalls: '1. 分组键选择错误：选择了不合适的分组键，导致分组结果不符合预期。\n2. 聚合函数选择错误：选择了不适合数据类型的聚合函数，导致错误或无意义的结果。\n3. 内存使用：分组操作在大型数据集上可能消耗大量内存。\n4. 性能问题：复杂的分组和聚合操作可能性能较差。\n5. 多级分组复杂性：多级分组的操作较为复杂，容易出错。\n6. 索引混乱：分组后的数据索引可能变得混乱，需要重新整理。', order: 4, duration: '60分钟' },
          { id: 5, course_id: 6, title: '窗口函数', content: '窗口函数是Pandas中用于时间序列和滚动分析的重要工具。在本课时中，我们将详细学习：\n\n1. 窗口类型：\n   - 滚动窗口（rolling）\n   - 扩展窗口（expanding）\n   - 指数加权窗口（ewm）\n   - 时间窗口\n\n2. 窗口参数：\n   - window 参数\n   - min_periods 参数\n   - center 参数\n   - win_type 参数\n\n3. 窗口函数应用：\n   - 统计函数（mean, sum, std等）\n   - 自定义函数\n   - 多函数应用\n   - 窗口结果可视化\n\n4. 高级窗口技巧：\n   - 滚动统计\n   - 移动平均线\n   - 滚动相关性\n   - 窗口异常检测\n\n5. 性能优化：\n   - 窗口大小选择\n   - 函数选择\n   - 内存使用\n   - 大型数据窗口操作\n\n通过本课时的学习，您将掌握Pandas的窗口函数技巧，能够进行时间序列分析和滚动统计。', pitfalls: '1. 窗口大小选择不当：选择了不合适的窗口大小，导致结果不准确。\n2. 性能问题：窗口操作在大型数据集上可能性能较差。\n3. 内存使用：窗口操作可能消耗大量内存，特别是在大型数据集上。\n4. 边界效应：窗口操作的边界效应可能导致结果偏差。\n5. 函数选择错误：选择了不适合窗口操作的函数，导致错误或无意义的结果。\n6. 时间序列处理：时间序列的窗口操作需要注意时间索引的正确性。', order: 5, duration: '60分钟' },
          { id: 6, course_id: 6, title: '时间序列处理', content: '时间序列处理是Pandas的重要应用领域。在本课时中，我们将详细学习：\n\n1. 时间索引：\n   - DatetimeIndex\n   - PeriodIndex\n   - TimedeltaIndex\n   - 时间索引创建\n\n2. 时间序列操作：\n   - 时间范围生成\n   - 时间重采样\n   - 时间偏移\n   - 时间差计算\n\n3. 时间序列分析：\n   - 趋势分析\n   - 季节性分析\n   - 周期性分析\n   - 异常检测\n\n4. 高级时间序列处理：\n   - 时区处理\n   - 夏令时处理\n   - 时间序列对齐\n   - 多时间序列分析\n\n5. 时间序列工具：\n   - resample() 方法\n   - asfreq() 方法\n   - shift() 方法\n   - diff() 方法\n\n通过本课时的学习，您将掌握Pandas的时间序列处理技巧，能够有效地分析和处理时间相关的数据。', pitfalls: '1. 时区处理错误：时区处理不当，导致时间计算错误。\n2. 时间格式问题：时间格式不正确，导致解析错误。\n3. 重采样错误：重采样方法选择不当，导致结果不准确。\n4. 性能问题：时间序列操作在大型数据集上可能性能较差。\n5. 内存使用：时间序列数据可能消耗大量内存。\n6. 缺失值处理：时间序列中的缺失值处理不当，导致分析结果偏差。', order: 6, duration: '60分钟' },
          { id: 7, course_id: 6, title: '文本数据处理', content: '文本数据处理是Pandas的重要功能之一。在本课时中，我们将详细学习：\n\n1. 文本数据类型：\n   - object 类型\n   - StringDtype 类型\n   - 文本数据特性\n\n2. 字符串方法：\n   - str 属性\n   - 字符串操作（split, replace, strip等）\n   - 正则表达式\n   - 字符串匹配\n\n3. 文本数据处理：\n   - 文本清洗\n   - 文本标准化\n   - 文本提取\n   - 文本转换\n\n4. 高级文本处理：\n   - 分词\n   - 停用词移除\n   - 词频统计\n   - 文本特征提取\n\n5. 性能优化：\n   - 向量化操作\n   - 内存使用\n   - 大型文本数据处理\n   - 并行处理\n\n通过本课时的学习，您将掌握Pandas的文本数据处理技巧，能够有效地处理和分析文本数据。', pitfalls: '1. 性能问题：文本处理在大型数据集上可能性能较差。\n2. 内存使用：文本数据可能消耗大量内存。\n3. 正则表达式错误：正则表达式语法错误，导致匹配失败。\n4. 编码问题：文本编码处理不当，导致乱码或错误。\n5. 方法选择不当：选择了不适合任务的文本处理方法，导致效率低下。\n6. 结果验证不足：没有验证文本处理结果，导致错误未被发现。', order: 7, duration: '60分钟' },
          { id: 8, course_id: 6, title: '数据透视表', content: '数据透视表是Pandas中用于数据汇总和分析的强大工具。在本课时中，我们将详细学习：\n\n1. 数据透视表基础：\n   - pivot_table() 函数\n   - 基本参数\n   - 聚合函数\n   - 索引和列\n\n2. 高级数据透视表：\n   - 多级索引\n   - 多个聚合函数\n   - 自定义聚合函数\n   - 边际汇总\n\n3. 数据透视表操作：\n   - 数据透视表转换\n   - 数据透视表过滤\n   - 数据透视表排序\n   - 数据透视表可视化\n\n4. 交叉表：\n   - crosstab() 函数\n   - 频率表\n   - 列联表\n   - 卡方检验\n\n5. 性能优化：\n   - 数据透视表优化\n   - 内存使用\n   - 大型数据处理\n   - 并行计算\n\n通过本课时的学习，您将掌握Pandas的数据透视表技巧，能够有效地汇总和分析复杂数据。', pitfalls: '1. 参数设置错误：数据透视表参数设置错误，导致结果不符合预期。\n2. 内存使用：数据透视表在大型数据集上可能消耗大量内存。\n3. 性能问题：复杂的数据透视表操作可能性能较差。\n4. 索引混乱：数据透视表的多级索引可能变得混乱，需要重新整理。\n5. 聚合函数选择错误：选择了不适合数据类型的聚合函数，导致错误或无意义的结果。\n6. 结果验证不足：没有验证数据透视表结果，导致错误未被发现。', order: 8, duration: '60分钟' },
          { id: 9, course_id: 6, title: '性能优化', content: '性能优化是Pandas应用中的重要考虑因素。在本课时中，我们将详细学习：\n\n1. 性能评估：\n   - 时间测量\n   - 内存使用分析\n   - 瓶颈识别\n   - 性能基准测试\n\n2. 内存优化：\n   - 数据类型优化\n   - 内存使用监控\n   - 数据压缩\n   - 惰性计算\n\n3. 计算优化：\n   - 向量化操作\n   - 避免循环\n   - 适当使用apply\n   - 并行计算\n\n4. 索引优化：\n   - 索引类型选择\n   - 索引排序\n   - 索引重建\n   - 多级索引优化\n\n5. 大型数据处理：\n   - 分块处理\n   - 磁盘缓存\n   - 内存映射\n   - 外部库集成\n\n通过本课时的学习，您将掌握Pandas的性能优化技巧，能够处理大型数据集并提高代码效率。', pitfalls: '1. 过度优化：过度优化代码，导致可读性和可维护性下降。\n2. 优化方向错误：优化了非瓶颈部分，没有显著提高性能。\n3. 内存使用监控不足：没有监控内存使用，导致内存不足问题。\n4. 数据类型选择错误：选择了不适合的数据类型，导致内存使用过高。\n5. 并行计算滥用：在不适合的场景下使用并行计算，导致性能下降。\n6. 代码可读性牺牲：为了性能优化牺牲了代码可读性，导致维护困难。', order: 9, duration: '60分钟' },
          { id: 10, course_id: 6, title: 'Pandas实战案例', content: 'Pandas实战案例是对Pandas技术的综合应用。在本课时中，我们将通过实际案例学习：\n\n1. 案例背景：\n   - 数据来源和特点\n   - 分析目标\n   - 技术挑战\n   - 预期成果\n\n2. 数据处理流程：\n   - 数据读取和初步分析\n   - 数据清洗和预处理\n   - 数据转换和整合\n   - 数据汇总和分析\n   - 结果可视化\n\n3. 核心技术应用：\n   - 高级索引和选择\n   - 数据合并和连接\n   - 分组和聚合\n   - 时间序列处理\n   - 文本数据处理\n\n4. 性能优化：\n   - 内存使用优化\n   - 计算效率提升\n   - 代码结构优化\n   - 并行处理\n\n5. 经验总结：\n   - 成功经验\n   - 遇到的挑战\n   - 解决方案\n   - 改进建议\n\n通过本课时的学习，您将掌握实际Pandas项目的开发方法，能够独立完成复杂的数据处理任务。', pitfalls: '1. 项目范围过大：选择了过于复杂的项目，导致无法在有限时间内完成。\n2. 数据质量差：原始数据质量差，导致处理工作量大。\n3. 技术选择不当：选择了不适合任务的Pandas方法，导致效率低下。\n4. 性能问题：处理大型数据集时遇到性能瓶颈。\n5. 错误处理不足：没有充分处理可能出现的错误，导致程序不稳定。\n6. 文档记录不足：没有详细记录处理过程，导致后续无法重现。', order: 10, duration: '60分钟' },
          { id: 11, course_id: 6, title: '项目实践准备', content: '项目实践准备是确保Pandas项目成功的重要步骤。在本课时中，我们将详细学习：\n\n1. 项目需求分析：\n   - 目标数据定义\n   - 分析范围确定\n   - 数据质量要求\n   - 时间和资源限制\n\n2. 技术方案设计：\n   - 数据处理流程\n   - 技术栈确定\n   - 工具选择\n   - 性能考量\n\n3. 数据准备：\n   - 数据来源确认\n   - 数据格式分析\n   - 数据质量评估\n   - 数据获取计划\n\n4. 开发环境设置：\n   - Python环境配置\n   - Pandas版本选择\n   - 依赖管理\n   - 版本控制\n\n5. 项目管理：\n   - 任务分解\n   - 时间线规划\n   - 里程碑设定\n   - 风险评估\n\n通过本课时的学习，您将掌握Pandas项目的准备方法，能够制定科学合理的项目计划。', pitfalls: '1. 需求分析不充分：没有充分分析项目需求，导致开发过程中频繁变更。\n2. 技术方案选择错误：选择了不适合项目需求的技术方案，导致开发困难。\n3. 数据准备不足：没有充分准备数据，导致开发过程中遇到数据问题。\n4. 环境配置问题：开发环境配置不当，导致依赖冲突或版本不兼容。\n5. 计划制定不合理：制定了不合理的开发计划，导致项目延期。\n6. 风险评估不足：没有充分评估项目风险，导致遇到意外问题时无法应对。', order: 11, duration: '60分钟' },
          { id: 12, course_id: 6, title: '项目展示与总结', content: '项目展示与总结是Pandas项目的最后环节。在本课时中，我们将详细学习：\n\n1. 成果整理：\n   - 分析结果汇总\n   - 关键发现提取\n   - 可视化材料准备\n   - 报告撰写\n\n2. 展示技巧：\n   - 受众分析\n   - 内容组织\n   - 演示方法\n   - 时间管理\n\n3. 沟通技巧：\n   - 清晰表达\n   - 故事讲述\n   - 问答准备\n   - 反馈处理\n\n4. 项目总结：\n   - 项目回顾\n   - 经验教训\n   - 成功因素分析\n   - 改进建议\n\n5. 后续行动：\n   - 实施计划\n   - 监控方案\n   - 持续改进\n   - 知识共享\n\n通过本课时的学习，您将掌握如何有效地展示和总结Pandas项目成果，确保项目价值得到充分体现。', pitfalls: '1. 展示内容过多：在有限的时间内展示过多内容，导致重点不突出。\n2. 技术术语过多：使用了过多的技术术语，导致非技术人员难以理解。\n3. 数据可视化不当：创建了过于复杂或不清晰的可视化图表。\n4. 故事性不足：没有将分析结果组织成一个连贯的故事，导致听众难以跟随。\n5. 问答准备不足：没有充分准备可能的问题，导致在问答环节表现不佳。\n6. 总结不全面：没有全面总结项目经验和教训，无法为未来项目提供参考。', order: 12, duration: '60分钟' }
        ],
        7: [
          { id: 1, course_id: 7, title: 'Pandas高级索引', content: 'Pandas高级索引是Pandas库的高级功能。在本课时中，我们将详细学习：\n\n1. 索引类型进阶：\n   - 整数索引的高级操作\n   - 标签索引的高级操作\n   - 布尔索引的高级应用\n   - 多级索引的高级操作\n\n2. 索引创建与修改：\n   - 自定义索引\n   - 索引重命名\n   - 索引排序\n   - 索引重置\n   - 索引设置\n\n3. 高级索引技巧：\n   - 条件索引\n   - 函数式索引\n   - 链式索引\n   - 索引的向量化操作\n\n4. 索引性能优化：\n   - 索引类型选择\n   - 索引内存使用\n   - 索引查询速度\n   - 大型数据集索引优化\n\n5. 实战应用：\n   - 复杂条件查询\n   - 多维度数据选择\n   - 高性能数据访问\n   - 索引在数据分析中的应用\n\n通过本课时的学习，您将掌握Pandas的高级索引技术，能够更高效地访问和操作数据。', pitfalls: '1. 索引类型混淆：混淆了不同类型的索引，导致操作错误。\n2. 性能问题：索引操作在大型数据集上可能性能较差。\n3. 内存使用：某些索引操作可能会创建数据的副本，增加内存使用。\n4. 链式索引警告：使用链式操作修改数据时出现警告。\n5. 多级索引复杂性：多级索引的操作较为复杂，容易出错。\n6. 索引对齐：Pandas的索引对齐特性可能导致意外的结果。', order: 1, duration: '45分钟' },
          { id: 2, course_id: 7, title: '高级数据转换', content: '高级数据转换是Pandas的重要功能。在本课时中，我们将详细学习：\n\n1. 数据转换方法：\n   - map() 方法\n   - apply() 方法\n   - applymap() 方法\n   - transform() 方法\n   - agg() 方法\n\n2. 自定义函数应用：\n   - 向量化函数\n   - 元素级函数\n   - 行/列级函数\n   - 聚合函数\n\n3. 高级转换技巧：\n   - 条件转换\n   - 多列转换\n   - 链式转换\n   - 转换后的数据验证\n\n4. 性能优化：\n   - 向量化操作\n   - 避免循环\n   - 适当使用apply\n   - 并行处理\n\n5. 实战应用：\n   - 数据标准化\n   - 特征工程\n   - 数据清洗\n   - 复杂数据转换\n\n通过本课时的学习，您将掌握Pandas的高级数据转换技巧，能够更灵活地处理和转换数据。', pitfalls: '1. 性能问题：apply()方法在大型数据集上可能性能较差。\n2. 内存使用：某些转换操作可能会创建数据的副本，增加内存使用。\n3. 函数选择错误：选择了不适合任务的转换函数，导致效率低下。\n4. 错误处理不足：没有处理转换过程中可能出现的错误。\n5. 结果验证不足：没有验证转换结果，导致错误未被发现。\n6. 代码可读性：复杂的转换操作可能导致代码可读性下降。', order: 2, duration: '60分钟' },
          { id: 3, course_id: 7, title: '高级分组操作', content: '高级分组操作是Pandas的强大功能。在本课时中，我们将详细学习：\n\n1. 分组键进阶：\n   - 多键分组\n   - 函数分组\n   - 时间分组\n   - 条件分组\n\n2. 分组对象操作：\n   - 分组对象属性\n   - 分组对象方法\n   - 分组后的数据访问\n   - 分组迭代\n\n3. 高级聚合：\n   - 多函数聚合\n   - 命名聚合\n   - 自定义聚合函数\n   - 聚合结果重塑\n\n4. 分组转换与过滤：\n   - transform() 方法高级应用\n   - filter() 方法高级应用\n   - apply() 方法在分组中的应用\n   - 分组后的数据处理\n\n5. 性能优化：\n   - 分组键选择\n   - 聚合函数选择\n   - 内存使用\n   - 大型数据分组\n\n通过本课时的学习，您将掌握Pandas的高级分组操作技巧，能够更灵活地对数据进行分组和分析。', pitfalls: '1. 分组键选择错误：选择了不合适的分组键，导致分组结果不符合预期。\n2. 聚合函数选择错误：选择了不适合数据类型的聚合函数，导致错误或无意义的结果。\n3. 内存使用：分组操作在大型数据集上可能消耗大量内存。\n4. 性能问题：复杂的分组和聚合操作可能性能较差。\n5. 多级分组复杂性：多级分组的操作较为复杂，容易出错。\n6. 索引混乱：分组后的数据索引可能变得混乱，需要重新整理。', order: 3, duration: '60分钟' },
          { id: 4, course_id: 7, title: '多级索引', content: '多级索引是Pandas中处理复杂数据的重要工具。在本课时中，我们将详细学习：\n\n1. 多级索引创建：\n   - from_tuples()\n   - from_arrays()\n   - from_product()\n   - set_index()\n   - pivot_table()\n\n2. 多级索引操作：\n   - 索引访问\n   - 索引切片\n   - 索引排序\n   - 索引重命名\n   - 索引重置\n\n3. 多级索引高级技巧：\n   - 多级索引转换\n   - 多级索引堆叠\n   - 多级索引拆分\n   - 多级索引对齐\n\n4. 多级索引性能：\n   - 内存使用\n   - 查询速度\n   - 大型数据处理\n   - 优化策略\n\n5. 实战应用：\n   - 时间序列数据\n   - 多维度数据\n   - 层次化数据\n   - 复杂数据结构\n\n通过本课时的学习，您将掌握Pandas的多级索引技术，能够更有效地处理和分析复杂数据。', pitfalls: '1. 索引操作复杂：多级索引的操作较为复杂，容易出错。\n2. 性能问题：多级索引在大型数据集上可能性能较差。\n3. 内存使用：多级索引可能消耗大量内存。\n4. 索引对齐：多级索引的对齐特性可能导致意外的结果。\n5. 代码可读性：复杂的多级索引操作可能导致代码可读性下降。\n6. 调试困难：多级索引的错误可能难以调试。', order: 4, duration: '60分钟' },
          { id: 5, course_id: 7, title: '时间序列高级分析', content: '时间序列高级分析是Pandas的重要应用领域。在本课时中，我们将详细学习：\n\n1. 时间索引进阶：\n   - 时区处理\n   - 夏令时处理\n   - 时间偏移\n   - 时间范围生成\n\n2. 时间序列操作：\n   - 重采样高级应用\n   - 滚动窗口\n   - 指数加权窗口\n   - 时间序列对齐\n\n3. 时间序列分析：\n   - 趋势提取\n   - 季节性分析\n   - 周期性检测\n   - 异常检测\n   - 预测\n\n4. 高级时间序列工具：\n   - resample() 高级应用\n   - asfreq() 高级应用\n   - shift() 和 diff()\n   - 时间序列绘图\n\n5. 实战应用：\n   - 金融时间序列\n   - 销售数据分析\n   - 传感器数据处理\n   - 预测模型构建\n\n通过本课时的学习，您将掌握Pandas的时间序列高级分析技术，能够更深入地分析和处理时间相关的数据。', pitfalls: '1. 时区处理错误：时区处理不当，导致时间计算错误。\n2. 时间格式问题：时间格式不正确，导致解析错误。\n3. 重采样错误：重采样方法选择不当，导致结果不准确。\n4. 性能问题：时间序列操作在大型数据集上可能性能较差。\n5. 内存使用：时间序列数据可能消耗大量内存。\n6. 缺失值处理：时间序列中的缺失值处理不当，导致分析结果偏差。', order: 5, duration: '60分钟' },
          { id: 6, course_id: 7, title: '数据可视化集成', content: '数据可视化集成是Pandas的重要功能。在本课时中，我们将详细学习：\n\n1. Pandas绘图基础：\n   - plot() 方法\n   - 绘图参数\n   - 图表类型\n   - 绘图风格\n\n2. 与Matplotlib集成：\n   - 基本集成\n   - 图表定制\n   - 多子图\n   - 交互式图表\n\n3. 与Seaborn集成：\n   - 统计图表\n   - 主题设置\n   - 颜色面板\n   - 高级可视化\n\n4. 与其他可视化库集成：\n   - Plotly\n   - Bokeh\n   - Altair\n   - 其他库\n\n5. 可视化最佳实践：\n   - 图表选择\n   - 颜色使用\n   - 标签和标题\n   - 交互式元素\n   - 性能优化\n\n通过本课时的学习，您将掌握Pandas与数据可视化库的集成技巧，能够创建更加丰富和有效的数据可视化。', pitfalls: '1. 图表类型选择错误：选择了不适合数据类型的图表类型，导致信息传达不清。\n2. 可视化过度：创建了过多或过于复杂的图表，导致信息过载。\n3. 性能问题：大型数据集的可视化可能性能较差。\n4. 内存使用：某些可视化操作可能消耗大量内存。\n5. 美观性不足：图表设计不美观，影响信息传达效果。\n6. 交互性不足：在需要交互的场景中使用了静态图表，降低了用户体验。', order: 6, duration: '60分钟' },
          { id: 7, course_id: 7, title: '大数据处理', content: '大数据处理是Pandas的重要应用场景。在本课时中，我们将详细学习：\n\n1. 大数据挑战：\n   - 内存限制\n   - 计算速度\n   - I/O瓶颈\n   - 可扩展性\n\n2. 内存优化：\n   - 数据类型优化\n   - 内存使用监控\n   - 数据压缩\n   - 惰性计算\n\n3. 分块处理：\n   - 读取大文件\n   - 分块计算\n   - 分块聚合\n   - 分块合并\n\n4. 外部存储：\n   - HDF5\n   - Parquet\n   - Feather\n   - 其他格式\n\n5. 并行处理：\n   - Dask集成\n   - 多进程处理\n   - 分布式计算\n   - 性能优化\n\n通过本课时的学习，您将掌握Pandas处理大数据的技巧，能够有效地处理和分析大型数据集。', pitfalls: '1. 内存不足：处理大型数据集时可能出现内存不足的问题。\n2. 性能问题：大数据处理可能性能较差，需要较长时间。\n3. 分块策略不当：分块大小选择不当，导致处理效率低下。\n4. 外部存储选择错误：选择了不适合的数据格式，导致I/O性能差。\n5. 并行处理配置错误：并行处理配置不当，导致性能下降或错误。\n6. 错误处理不足：大数据处理过程中可能出现的错误没有得到充分处理。', order: 7, duration: '60分钟' },
          { id: 8, course_id: 7, title: '并行计算', content: '并行计算是提高Pandas性能的重要方法。在本课时中，我们将详细学习：\n\n1. 并行计算基础：\n   - 并行计算概念\n   - 并行计算优势\n   - 并行计算挑战\n   - 并行计算适用场景\n\n2. Pandas并行工具：\n   - Dask\n   - Swifter\n   - Pandarallel\n   - 其他库\n\n3. 并行计算实现：\n   - 多进程处理\n   - 多线程处理\n   - 分布式计算\n   - GPU加速\n\n4. 并行计算优化：\n   - 任务划分\n   - 负载均衡\n   - 通信开销\n   - 内存使用\n\n5. 实战应用：\n   - 大型数据处理\n   - 复杂计算\n   - 模型训练\n   - 数据预处理\n\n通过本课时的学习，您将掌握Pandas的并行计算技巧，能够大幅提高数据处理和分析的效率。', pitfalls: '1. 并行开销：并行计算的开销可能超过其带来的性能提升。\n2. 内存使用：并行计算可能消耗更多内存。\n3. 线程安全：某些操作可能不是线程安全的，导致错误。\n4. 调试困难：并行计算的错误可能难以调试。\n5. 环境依赖：某些并行工具可能有复杂的环境依赖。\n6. 可移植性：并行代码可能在不同环境中表现不同。', order: 8, duration: '60分钟' },
          { id: 9, course_id: 7, title: 'Pandas实战案例', content: 'Pandas实战案例是对Pandas高级技术的综合应用。在本课时中，我们将通过实际案例学习：\n\n1. 案例背景：\n   - 数据来源和特点\n   - 分析目标\n   - 技术挑战\n   - 预期成果\n\n2. 数据处理流程：\n   - 数据读取和初步分析\n   - 数据清洗和预处理\n   - 高级数据转换和整合\n   - 复杂数据汇总和分析\n   - 结果可视化\n\n3. 核心技术应用：\n   - 高级索引和选择\n   - 高级数据转换\n   - 高级分组和聚合\n   - 多级索引\n   - 时间序列高级分析\n   - 大数据处理\n\n4. 性能优化：\n   - 内存使用优化\n   - 计算效率提升\n   - 并行处理\n   - 代码结构优化\n\n5. 经验总结：\n   - 成功经验\n   - 遇到的挑战\n   - 解决方案\n   - 改进建议\n\n通过本课时的学习，您将掌握实际Pandas项目的开发方法，能够独立完成复杂的数据处理和分析任务。', pitfalls: '1. 项目范围过大：选择了过于复杂的项目，导致无法在有限时间内完成。\n2. 数据质量差：原始数据质量差，导致处理工作量大。\n3. 技术选择不当：选择了不适合任务的Pandas方法，导致效率低下。\n4. 性能问题：处理大型数据集时遇到性能瓶颈。\n5. 错误处理不足：没有充分处理可能出现的错误，导致程序不稳定。\n6. 文档记录不足：没有详细记录处理过程，导致后续无法重现。', order: 9, duration: '60分钟' },
          { id: 10, course_id: 7, title: '项目总结与展望', content: '项目总结与展望是Pandas高级应用课程的最后环节。在本课时中，我们将详细学习：\n\n1. 项目回顾：\n   - 项目目标达成情况\n   - 技术实现总结\n   - 遇到的挑战\n   - 解决方案\n\n2. 经验教训：\n   - 技术选择\n   - 性能优化\n   - 错误处理\n   - 代码质量\n   - 团队协作\n\n3. 最佳实践：\n   - Pandas编程规范\n   - 性能优化技巧\n   - 错误处理策略\n   - 文档记录\n   - 代码复用\n\n4. 行业趋势：\n   - Pandas发展方向\n   - 大数据处理趋势\n   - 并行计算发展\n   - 可视化技术演进\n   - 与其他库的集成\n\n5. 未来展望：\n   - 技术改进方向\n   - 应用场景拓展\n   - 自动化和智能化\n   - 标准化和规范化\n   - 社区贡献\n\n通过本课时的学习，您将总结Pandas项目的经验教训，为未来的Pandas应用提供参考。', pitfalls: '1. 总结不全面：没有全面总结项目经验和教训，导致无法为未来项目提供参考。\n2. 经验教训分析不深入：对经验教训的分析不够深入，无法从中学习。\n3. 最佳实践提炼不足：没有提炼出有价值的最佳实践，影响后续项目。\n4. 行业趋势把握不准确：对行业趋势的把握不准确，导致技术选型落后。\n5. 未来规划不实际：未来规划过于理想化，无法实现。\n6. 学习资源推荐不实用：推荐的学习资源不实用，对后续学习帮助不大。', order: 10, duration: '60分钟' }
        ],
        8: [
          { id: 1, course_id: 8, title: '商业数据分析概述', content: '商业数据分析概述是商业数据分析课程的第一课时。在本课时中，我们将详细学习：\n\n1. 商业数据分析的基本概念：\n   - 什么是商业数据分析\n   - 商业数据分析的重要性\n   - 商业数据分析的应用场景\n\n2. 商业数据分析的基本流程：\n   - 问题定义\n   - 数据收集\n   - 数据清洗\n   - 数据探索\n   - 数据分析\n   - 结果呈现\n   - 决策支持\n\n3. 商业数据分析的工具和技术：\n   - Excel\n   - Python\n   - SQL\n   - 商业智能工具\n\n4. 商业数据分析的职业发展：\n   - 数据分析师的职责\n   - 所需技能和能力\n   - 职业发展路径\n\n通过本课时的学习，您将对商业数据分析有一个全面的认识，为后续的学习打下基础。', pitfalls: '1. 对商业数据分析的理解过于狭隘：认为商业数据分析只是简单的统计计算，忽略了其在业务决策中的重要作用。\n2. 流程理解不清晰：不了解商业数据分析的完整流程，导致在实际项目中无从下手。\n3. 工具选择不当：选择了不适合自己需求的工具，影响分析效率。\n4. 期望过高：对商业数据分析的结果期望过高，忽视了数据质量和分析方法的局限性。\n5. 缺乏业务知识：只关注技术实现，忽视了业务背景和需求。', order: 1, duration: '45分钟' },
          { id: 2, course_id: 8, title: '销售数据分析', content: '销售数据分析是商业数据分析的重要组成部分。在本课时中，我们将详细学习：\n\n1. 销售数据的类型：\n   - 销售金额\n   - 销售数量\n   - 销售渠道\n   - 销售区域\n   - 销售时间\n\n2. 销售数据分析方法：\n   - 销售趋势分析\n   - 销售季节性分析\n   - 销售地区分析\n   - 产品销售分析\n   - 客户销售分析\n\n3. 销售数据分析工具：\n   - Excel透视表\n   - Python Pandas\n   - 数据可视化工具\n\n4. 销售数据分析的应用：\n   - 销售预测\n   - 库存管理\n   - 价格策略\n   - 促销效果评估\n\n通过本课时的学习，您将掌握销售数据分析的基本方法和技巧，能够从销售数据中发现有价值的信息。', pitfalls: '1. 数据质量问题：使用了质量差的销售数据，导致分析结果不可靠。\n2. 分析深度不足：只进行了表面分析，没有深入挖掘数据背后的原因。\n3. 可视化不当：创建了过于复杂或不清晰的图表，影响信息传达。\n4. 缺乏业务视角：没有从业务角度进行分析，导致发现的信息对业务决策没有帮助。\n5. 忽略季节性因素：没有考虑销售的季节性因素，导致分析结果偏差。', order: 2, duration: '60分钟' },
          { id: 3, course_id: 8, title: '客户行为分析', content: '客户行为分析是商业数据分析的重要组成部分。在本课时中，我们将详细学习：\n\n1. 客户行为数据的类型：\n   - 购买行为\n   - 浏览行为\n   - 点击行为\n   - 停留时间\n   - 反馈行为\n\n2. 客户行为分析方法：\n   - 客户细分\n   - 客户生命周期分析\n   - 客户购买路径分析\n   - 客户流失分析\n   - 客户满意度分析\n\n3. 客户行为分析工具：\n   - 客户关系管理系统\n   - 网站分析工具\n   - Python数据分析库\n   - 数据可视化工具\n\n4. 客户行为分析的应用：\n   - 个性化推荐\n   - 客户留存策略\n   - 精准营销\n   - 产品改进\n\n通过本课时的学习，您将掌握客户行为分析的基本方法和技巧，能够从客户行为数据中发现有价值的信息。', pitfalls: '1. 数据隐私问题：在分析客户行为数据时没有考虑数据隐私，可能导致法律风险。\n2. 分析维度单一：只从单一维度分析客户行为，导致分析结果不全面。\n3. 过度分析：分析了与业务无关的客户行为，浪费时间和资源。\n4. 缺乏长期跟踪：没有长期跟踪客户行为，无法了解客户行为的变化趋势。\n5. 忽略客户异质性：没有考虑不同客户群体的差异，导致分析结果过于笼统。', order: 3, duration: '60分钟' },
          { id: 4, course_id: 8, title: '市场分析', content: '市场分析是商业数据分析的重要组成部分。在本课时中，我们将详细学习：\n\n1. 市场数据的类型：\n   - 市场规模\n   - 市场份额\n   - 市场增长率\n   - 市场趋势\n   - 竞争对手数据\n\n2. 市场分析方法：\n   - SWOT分析\n   - PEST分析\n   - 波特五力分析\n   - 市场细分分析\n   - 市场机会分析\n\n3. 市场分析工具：\n   - 市场调研工具\n   - 数据分析软件\n   - 数据可视化工具\n   - 市场预测工具\n\n4. 市场分析的应用：\n   - 市场进入策略\n   - 产品定位\n   - 价格策略\n   - 渠道策略\n   - 竞争策略\n\n通过本课时的学习，您将掌握市场分析的基本方法和技巧，能够从市场数据中发现有价值的信息。', pitfalls: '1. 数据来源单一：只使用了单一来源的市场数据，导致分析结果不全面。\n2. 分析方法选择不当：选择了不适合市场类型的分析方法，导致分析结果不准确。\n3. 缺乏行业知识：不了解行业特点，导致分析结果与实际情况不符。\n4. 忽视宏观环境：没有考虑宏观环境对市场的影响，导致分析结果偏差。\n5. 过度依赖历史数据：过度依赖历史数据，忽视了市场的变化趋势。', order: 4, duration: '60分钟' },
          { id: 5, course_id: 8, title: '竞争分析', content: '竞争分析是商业数据分析的重要组成部分。在本课时中，我们将详细学习：\n\n1. 竞争对手数据的类型：\n   - 产品信息\n   - 价格信息\n   - 市场份额\n   - 营销策略\n   - 财务数据\n\n2. 竞争分析方法：\n   - 竞争对手识别\n   - 竞争对手分析\n   - 竞争优势分析\n   - 竞争策略制定\n   - 竞争态势监测\n\n3. 竞争分析工具：\n   - 竞争情报系统\n   - 数据分析软件\n   - 市场调研工具\n   - 数据可视化工具\n\n4. 竞争分析的应用：\n   - 产品差异化\n   - 价格策略\n   - 营销策略\n   - 市场定位\n   - 战略规划\n\n通过本课时的学习，您将掌握竞争分析的基本方法和技巧，能够从竞争对手数据中发现有价值的信息。', pitfalls: '1. 数据收集困难：竞争对手数据收集困难，导致分析数据不足。\n2. 分析深度不足：只进行了表面分析，没有深入了解竞争对手的战略意图。\n3. 过度关注竞争对手：过度关注竞争对手，忽视了自身的优势和劣势。\n4. 缺乏动态分析：没有进行动态分析，无法了解竞争对手的变化趋势。\n5. 分析结果应用不当：分析结果没有有效地应用到业务决策中。', order: 5, duration: '60分钟' },
          { id: 6, course_id: 8, title: '商业报告撰写', content: '商业报告撰写是商业数据分析的重要环节。在本课时中，我们将详细学习：\n\n1. 商业报告的类型：\n   - 日常报告\n   - 定期报告\n   - 专题报告\n   - 战略报告\n\n2. 商业报告的结构：\n   - 标题和摘要\n   - 背景和目标\n   - 数据和方法\n   - 分析结果\n   - 结论和建议\n   - 附录\n\n3. 商业报告的撰写技巧：\n   - 清晰的结构\n   - 简洁的语言\n   - 有效的可视化\n   - 有说服力的论证\n   - 专业的格式\n\n4. 商业报告的呈现：\n   - 书面报告\n   - 口头汇报\n   - 演示文稿\n   - 交互式仪表板\n\n通过本课时的学习，您将掌握商业报告撰写的基本方法和技巧，能够有效地呈现分析结果。', pitfalls: '1. 结构混乱：报告结构混乱，逻辑不清，导致读者难以理解。\n2. 内容冗长：报告内容冗长，重点不突出，导致读者失去兴趣。\n3. 数据可视化不当：创建了过于复杂或不清晰的图表，影响信息传达。\n4. 语言不专业：使用了不专业的语言，影响报告的可信度。\n5. 缺乏针对性：报告缺乏针对性，没有满足特定读者的需求。', order: 6, duration: '60分钟' },
          { id: 7, course_id: 8, title: '案例分析', content: '案例分析是商业数据分析的重要实践。在本课时中，我们将通过实际案例学习：\n\n1. 案例背景：\n   - 零售企业概况\n   - 业务挑战\n   - 数据情况\n   - 分析目标\n\n2. 数据收集和预处理：\n   - 数据来源\n   - 数据清洗\n   - 数据整合\n   - 数据质量评估\n\n3. 数据分析：\n   - 销售数据分析\n   - 客户行为分析\n   - 市场分析\n   - 竞争分析\n\n4. 分析结果和建议：\n   - 关键发现\n   - 业务建议\n   - 实施计划\n   - 效果评估\n\n5. 案例总结：\n   - 成功经验\n   - 教训和启示\n   - 最佳实践\n   - 未来展望\n\n通过本课时的学习，您将掌握商业数据分析的实际应用方法，能够独立完成商业数据分析项目。', pitfalls: '1. 数据质量问题：使用了质量差的数据，导致分析结果不可靠。\n2. 分析目标不明确：没有明确的分析目标，导致分析方向混乱。\n3. 过度分析：分析了与业务无关的数据，浪费时间和资源。\n4. 结论不严谨：基于有限的数据得出过于绝对的结论。\n5. 缺乏业务知识：不了解业务背景，导致分析结果与实际业务需求不符。\n6. 报告表达不清：分析报告结构混乱，重点不突出，难以理解。', order: 7, duration: '90分钟' }
        ],
        9: [
          { id: 1, course_id: 9, title: '数据可视化基础', content: '数据可视化基础是商业数据可视化与预测课程的第一课时。在本课时中，我们将详细学习：\n\n1. 数据可视化的基本概念：\n   - 什么是数据可视化\n   - 数据可视化的重要性\n   - 数据可视化的应用场景\n\n2. 数据可视化的原则：\n   - 准确性\n   - 清晰性\n   - 简洁性\n   - 美观性\n   - 有效性\n\n3. 数据可视化的类型：\n   - 比较型图表\n   - 分布型图表\n   - 关系型图表\n   - 构成型图表\n   - 趋势型图表\n\n4. 数据可视化的工具：\n   - Excel\n   - Tableau\n   - Power BI\n   - Python库（Matplotlib、Seaborn等）\n   - R语言\n\n5. 数据可视化的流程：\n   - 数据准备\n   - 图表选择\n   - 图表设计\n   - 图表优化\n   - 图表呈现\n\n通过本课时的学习，您将掌握数据可视化的基本概念和原则，为后续的学习打下基础。', pitfalls: '1. 图表类型选择错误：选择了不适合数据类型的图表类型，导致信息传达不清。\n2. 可视化过度：创建了过多或过于复杂的图表，导致信息过载。\n3. 颜色使用不当：使用了不利于色盲人士阅读的颜色组合，或者颜色过多导致混乱。\n4. 缺乏标题和标签：没有为图表添加清晰的标题和标签，导致读者无法理解图表内容。\n5. 数据失真：通过不当的轴范围或图表类型使数据看起来与实际情况不符。', order: 1, duration: '60分钟' },
          { id: 2, course_id: 9, title: 'Matplotlib高级应用', content: 'Matplotlib高级应用是数据可视化的重要技术。在本课时中，我们将详细学习：\n\n1. Matplotlib基础：\n   - 安装和导入\n   - 基本图表创建\n   - 图表元素\n   - 基本配置\n\n2. 高级图表类型：\n   - 子图布局\n   - 多轴图表\n   - 3D图表\n   - 交互式图表\n   - 动画图表\n\n3. 图表定制：\n   - 颜色和样式\n   - 字体和文本\n   - 图例和标签\n   - 网格和背景\n   - 轴和刻度\n\n4. 数据可视化最佳实践：\n   - 选择合适的图表类型\n   - 优化图表设计\n   - 提高图表可读性\n   - 确保图表准确性\n\n5. 案例分析：\n   - 销售数据可视化\n   - 客户行为可视化\n   - 市场趋势可视化\n   - 竞争分析可视化\n\n通过本课时的学习，您将掌握Matplotlib的高级应用技巧，能够创建复杂和美观的图表。', pitfalls: '1. 图表过于复杂：创建了过于复杂的图表，导致信息传达不清。\n2. 代码组织混乱：Matplotlib代码组织混乱，难以维护和理解。\n3. 性能问题：创建大型或复杂图表时性能较差。\n4. 内存使用：创建多个图表时内存使用过高。\n5. 跨平台兼容性：不同平台上的图表显示效果可能不同。', order: 2, duration: '60分钟' },
          { id: 3, course_id: 9, title: 'Seaborn库使用', content: 'Seaborn库是基于Matplotlib的高级数据可视化库。在本课时中，我们将详细学习：\n\n1. Seaborn基础：\n   - 安装和导入\n   - 基本功能\n   - 内置数据集\n   - 主题设置\n\n2. Seaborn图表类型：\n   - 分类图表（catplot、boxplot、violinplot等）\n   - 分布图表（distplot、kdeplot、jointplot等）\n   - 关系图表（scatterplot、lineplot、regplot等）\n   - 矩阵图表（heatmap、clustermap等）\n   - 时间序列图表\n\n3. Seaborn高级功能：\n   - 调色板\n   - 风格设置\n   - 上下文设置\n   - 多图布局\n   - 自定义函数\n\n4. Seaborn与Pandas集成：\n   - DataFrame可视化\n   - 分组数据可视化\n   - 时间序列数据可视化\n   - 统计数据可视化\n\n5. 案例分析：\n   - 销售数据可视化\n   - 客户行为可视化\n   - 市场趋势可视化\n   - 竞争分析可视化\n\n通过本课时的学习，您将掌握Seaborn库的使用方法，能够创建美观和专业的统计图表。', pitfalls: '1. 依赖问题：Seaborn依赖于Matplotlib和Pandas，版本兼容性可能出现问题。\n2. 性能问题：处理大型数据集时性能较差。\n3. 自定义限制：某些高级定制可能需要直接使用Matplotlib。\n4. 内存使用：处理大型数据集时内存使用过高。\n5. 学习曲线：Seaborn的API相对复杂，需要一定的学习时间。', order: 3, duration: '60分钟' },
          { id: 4, course_id: 9, title: '交互式数据可视化', content: '交互式数据可视化是现代数据可视化的重要趋势。在本课时中，我们将详细学习：\n\n1. 交互式数据可视化的概念：\n   - 什么是交互式数据可视化\n   - 交互式数据可视化的优势\n   - 交互式数据可视化的应用场景\n\n2. 交互式数据可视化工具：\n   - Plotly\n   - Bokeh\n   - Dash\n   - Altair\n   - Tableau\n\n3. Plotly基础：\n   - 安装和导入\n   - 基本图表创建\n   - 交互功能\n   - 布局设置\n   - 导出和共享\n\n4. Bokeh基础：\n   - 安装和导入\n   - 基本图表创建\n   - 交互功能\n   - 布局设置\n   - 服务器应用\n\n5. 案例分析：\n   - 交互式销售仪表盘\n   - 交互式客户分析工具\n   - 交互式市场趋势分析\n   - 交互式竞争分析工具\n\n通过本课时的学习，您将掌握交互式数据可视化的基本方法和技巧，能够创建具有交互功能的图表和仪表盘。', pitfalls: '1. 性能问题：复杂的交互式可视化可能导致性能问题。\n2. 浏览器兼容性：不同浏览器的显示效果可能不同。\n3. 学习曲线：交互式可视化库的学习曲线较陡。\n4. 依赖问题：交互式可视化库的依赖较多，可能出现版本兼容性问题。\n5. 部署挑战：交互式可视化应用的部署可能比较复杂。', order: 4, duration: '60分钟' },
          { id: 5, course_id: 9, title: '时间序列分析', content: '时间序列分析是商业数据分析的重要方法。在本课时中，我们将详细学习：\n\n1. 时间序列的概念：\n   - 什么是时间序列\n   - 时间序列的特点\n   - 时间序列的类型\n   - 时间序列的应用场景\n\n2. 时间序列分析方法：\n   - 描述性分析\n   - 趋势分析\n   - 季节性分析\n   - 周期性分析\n   - 异常检测\n\n3. 时间序列可视化：\n   - 折线图\n   - 面积图\n   - 热力图\n   - 自相关图\n   - 偏自相关图\n\n4. 时间序列分析工具：\n   - Excel\n   - Python库（Pandas、StatsModels等）\n   - R语言\n   - 专业时间序列分析软件\n\n5. 案例分析：\n   - 销售时间序列分析\n   - 库存时间序列分析\n   - 网站流量时间序列分析\n   - 社交媒体时间序列分析\n\n通过本课时的学习，您将掌握时间序列分析的基本方法和技巧，能够分析和预测时间序列数据。', pitfalls: '1. 数据质量问题：时间序列数据质量差，导致分析结果不可靠。\n2. 模型选择错误：选择了不适合时间序列特性的模型，导致预测结果不准确。\n3. 过拟合：模型过度拟合历史数据，导致对未来的预测能力差。\n4. 季节性处理不当：没有正确处理时间序列的季节性，导致分析结果偏差。\n5. 缺乏业务知识：不了解业务背景，导致分析结果与实际情况不符。', order: 5, duration: '60分钟' },
          { id: 6, course_id: 9, title: '简单预测模型', content: '简单预测模型是商业预测的基础。在本课时中，我们将详细学习：\n\n1. 预测模型的基本概念：\n   - 什么是预测模型\n   - 预测模型的类型\n   - 预测模型的应用场景\n   - 预测模型的评估指标\n\n2. 简单预测方法：\n   - 移动平均法\n   - 指数平滑法\n   - 线性趋势法\n   - 季节性预测法\n   - 因果预测法\n\n3. 预测模型的建立步骤：\n   - 数据准备\n   - 模型选择\n   - 模型训练\n   - 模型评估\n   - 模型应用\n\n4. 预测模型的工具：\n   - Excel\n   - Python库（StatsModels、Scikit-learn等）\n   - R语言\n   - 专业预测软件\n\n5. 案例分析：\n   - 销售预测\n   - 库存预测\n   - 客户流失预测\n   - 市场需求预测\n\n通过本课时的学习，您将掌握简单预测模型的基本方法和技巧，能够构建和应用预测模型。', pitfalls: '1. 数据质量问题：使用了质量差的数据，导致预测结果不可靠。\n2. 模型选择错误：选择了不适合数据特性的预测模型，导致预测结果不准确。\n3. 过拟合：模型过度拟合历史数据，导致对未来的预测能力差。\n4. 预测范围不当：预测范围过大，导致预测结果不可靠。\n5. 缺乏业务知识：不了解业务背景，导致预测结果与实际情况不符。', order: 6, duration: '60分钟' },
          { id: 7, course_id: 9, title: '案例分析', content: '案例分析是商业数据可视化与预测的重要实践。在本课时中，我们将通过实际案例学习：\n\n1. 案例背景：\n   - 零售企业概况\n   - 业务挑战\n   - 数据情况\n   - 分析目标\n\n2. 数据收集和预处理：\n   - 数据来源\n   - 数据清洗\n   - 数据整合\n   - 数据质量评估\n\n3. 数据可视化分析：\n   - 销售趋势可视化\n   - 客户行为可视化\n   - 市场趋势可视化\n   - 竞争分析可视化\n\n4. 预测模型构建：\n   - 数据准备\n   - 模型选择\n   - 模型训练\n   - 模型评估\n   - 预测结果\n\n5. 分析结果和建议：\n   - 关键发现\n   - 业务建议\n   - 实施计划\n   - 效果评估\n\n6. 案例总结：\n   - 成功经验\n   - 教训和启示\n   - 最佳实践\n   - 未来展望\n\n通过本课时的学习，您将掌握商业数据可视化与预测的实际应用方法，能够独立完成数据可视化和预测项目。', pitfalls: '1. 数据质量问题：使用了质量差的数据，导致分析和预测结果不可靠。\n2. 分析目标不明确：没有明确的分析目标，导致分析方向混乱。\n3. 模型选择错误：选择了不适合数据特性的预测模型，导致预测结果不准确。\n4. 可视化不当：创建了过于复杂或不清晰的图表，影响信息传达。\n5. 缺乏业务知识：不了解业务背景，导致分析和预测结果与实际业务需求不符。', order: 7, duration: '90分钟' }
        ],
        10: [
          { id: 1, course_id: 10, title: '预测模型概述', content: '预测模型概述是商业预测模型课程的第一课时。在本课时中，我们将详细学习：\n\n1. 预测模型的基本概念：\n   - 什么是预测模型\n   - 预测模型的重要性\n   - 预测模型的应用场景\n   - 预测模型的类型\n\n2. 预测模型的基本流程：\n   - 问题定义\n   - 数据收集\n   - 数据预处理\n   - 模型选择\n   - 模型训练\n   - 模型评估\n   - 模型应用\n   - 模型监控\n\n3. 预测模型的评估指标：\n   - 误差指标（MAE、MSE、RMSE等）\n   - 准确率指标\n   - 召回率指标\n   - F1分数\n   - R²值\n\n4. 预测模型的工具和技术：\n   - Excel\n   - Python库（StatsModels、Scikit-learn等）\n   - R语言\n   - 专业预测软件\n\n5. 预测模型的挑战：\n   - 数据质量\n   - 模型选择\n   - 过拟合\n   - 模型解释性\n   - 模型更新\n\n通过本课时的学习，您将对预测模型有一个全面的认识，为后续的学习打下基础。', pitfalls: '1. 对预测模型的期望过高：认为预测模型可以完全准确地预测未来，忽视了预测的不确定性。\n2. 流程理解不清晰：不了解预测模型的完整流程，导致在实际项目中无从下手。\n3. 工具选择不当：选择了不适合自己需求的工具，影响预测效率和准确性。\n4. 评估指标选择错误：选择了不适合预测任务的评估指标，导致对模型性能的评估不准确。\n5. 缺乏业务知识：只关注技术实现，忽视了业务背景和需求。', order: 1, duration: '45分钟' },
          { id: 2, course_id: 10, title: '时间序列预测基础', content: '时间序列预测是预测模型的重要类型。在本课时中，我们将详细学习：\n\n1. 时间序列的基本概念：\n   - 什么是时间序列\n   - 时间序列的特点\n   - 时间序列的组成部分（趋势、季节性、周期性、噪声）\n   - 时间序列的类型\n\n2. 时间序列分析方法：\n   - 描述性分析\n   - 平稳性检验\n   - 自相关分析\n   - 偏自相关分析\n   - 谱分析\n\n3. 时间序列预测方法：\n   - 朴素预测法\n   - 移动平均法\n   - 指数平滑法\n   - ARIMA模型\n   - 季节性ARIMA模型\n\n4. 时间序列预测工具：\n   - Excel\n   - Python库（StatsModels、Prophet等）\n   - R语言\n   - 专业时间序列分析软件\n\n5. 案例分析：\n   - 销售预测\n   - 库存预测\n   - 网站流量预测\n   - 电力负荷预测\n\n通过本课时的学习，您将掌握时间序列预测的基本方法和技巧，能够构建和应用时间序列预测模型。', pitfalls: '1. 数据质量问题：时间序列数据质量差，导致预测结果不可靠。\n2. 模型选择错误：选择了不适合时间序列特性的模型，导致预测结果不准确。\n3. 过拟合：模型过度拟合历史数据，导致对未来的预测能力差。\n4. 季节性处理不当：没有正确处理时间序列的季节性，导致预测结果偏差。\n5. 预测范围不当：预测范围过大，导致预测结果不可靠。', order: 2, duration: '60分钟' },
          { id: 3, course_id: 10, title: '移动平均模型', content: '移动平均模型是时间序列预测的基础模型之一。在本课时中，我们将详细学习：\n\n1. 移动平均模型的基本概念：\n   - 什么是移动平均模型\n   - 移动平均模型的类型\n   - 移动平均模型的应用场景\n   - 移动平均模型的优缺点\n\n2. 简单移动平均（SMA）：\n   - 基本原理\n   - 窗口大小选择\n   - 计算方法\n   - 应用示例\n\n3. 加权移动平均（WMA）：\n   - 基本原理\n   - 权重选择\n   - 计算方法\n   - 应用示例\n\n4. 指数移动平均（EMA）：\n   - 基本原理\n   - 平滑系数选择\n   - 计算方法\n   - 应用示例\n\n5. 移动平均模型的评估：\n   - 误差计算\n   - 模型选择\n   - 性能评估\n   - 改进方法\n\n6. 案例分析：\n   - 销售预测\n   - 库存预测\n   - 价格预测\n   - 需求预测\n\n通过本课时的学习，您将掌握移动平均模型的基本原理和应用方法，能够构建和应用移动平均模型进行预测。', pitfalls: '1. 窗口大小选择不当：窗口大小选择不当，导致预测结果不准确。\n2. 权重选择不当：加权移动平均的权重选择不当，导致预测结果偏差。\n3. 平滑系数选择不当：指数移动平均的平滑系数选择不当，导致预测结果不准确。\n4. 对趋势和季节性处理不足：移动平均模型对趋势和季节性的处理能力有限。\n5. 对异常值敏感：移动平均模型对异常值较为敏感，可能导致预测结果偏差。', order: 3, duration: '60分钟' },
          { id: 4, course_id: 10, title: '指数平滑模型', content: '指数平滑模型是时间序列预测的重要模型之一。在本课时中，我们将详细学习：\n\n1. 指数平滑模型的基本概念：\n   - 什么是指数平滑模型\n   - 指数平滑模型的类型\n   - 指数平滑模型的应用场景\n   - 指数平滑模型的优缺点\n\n2. 简单指数平滑（SES）：\n   - 基本原理\n   - 平滑系数选择\n   - 计算方法\n   - 应用示例\n\n3. 双指数平滑（Holt）：\n   - 基本原理\n   - 平滑系数选择\n   - 计算方法\n   - 应用示例\n\n4. 三指数平滑（Holt-Winters）：\n   - 基本原理\n   - 平滑系数选择\n   - 计算方法\n   - 应用示例\n\n5. 指数平滑模型的评估：\n   - 误差计算\n   - 模型选择\n   - 性能评估\n   - 改进方法\n\n6. 案例分析：\n   - 销售预测\n   - 库存预测\n   - 价格预测\n   - 需求预测\n\n通过本课时的学习，您将掌握指数平滑模型的基本原理和应用方法，能够构建和应用指数平滑模型进行预测。', pitfalls: '1. 平滑系数选择不当：平滑系数选择不当，导致预测结果不准确。\n2. 对复杂模式处理不足：指数平滑模型对复杂的时间序列模式处理能力有限。\n3. 对异常值敏感：指数平滑模型对异常值较为敏感，可能导致预测结果偏差。\n4. 计算复杂度：高阶指数平滑模型的计算复杂度较高。\n5. 模型选择困难：不同类型的指数平滑模型适用于不同的时间序列模式，选择合适的模型较为困难。', order: 4, duration: '60分钟' },
          { id: 5, course_id: 10, title: '线性回归分析', content: '线性回归分析是预测模型的重要方法之一。在本课时中，我们将详细学习：\n\n1. 线性回归的基本概念：\n   - 什么是线性回归\n   - 线性回归的类型\n   - 线性回归的应用场景\n   - 线性回归的假设条件\n\n2. 简单线性回归：\n   - 基本原理\n   - 模型构建\n   - 参数估计\n   - 模型评估\n   - 应用示例\n\n3. 线性回归的评估指标：\n   - R²值\n   - 调整R²值\n   - F统计量\n   - t统计量\n   - p值\n   - 残差分析\n\n4. 线性回归的假设检验：\n   - 正态性检验\n   -  homoscedasticity检验\n   - 独立性检验\n   - 多重共线性检验\n\n5. 线性回归的应用：\n   - 销售预测\n   - 价格预测\n   - 需求预测\n   - 风险评估\n\n通过本课时的学习，您将掌握线性回归分析的基本原理和应用方法，能够构建和应用线性回归模型进行预测。', pitfalls: '1. 假设条件不满足：线性回归的假设条件不满足，导致模型结果不可靠。\n2. 过拟合：模型过度拟合训练数据，导致对新数据的预测能力差。\n3. 多重共线性：自变量之间存在多重共线性，导致模型不稳定。\n4. 异常值影响：异常值对线性回归模型的影响较大，可能导致模型结果偏差。\n5. 非线性关系：变量之间存在非线性关系，而使用线性模型进行拟合，导致模型结果不准确。', order: 5, duration: '60分钟' },
          { id: 6, course_id: 10, title: '多元回归分析', content: '多元回归分析是线性回归的扩展，用于处理多个自变量的情况。在本课时中，我们将详细学习：\n\n1. 多元回归的基本概念：\n   - 什么是多元回归\n   - 多元回归的应用场景\n   - 多元回归的假设条件\n   - 多元回归的优缺点\n\n2. 多元回归模型：\n   - 模型构建\n   - 参数估计\n   - 模型评估\n   - 变量选择\n   - 应用示例\n\n3. 多元回归的评估指标：\n   - R²值\n   - 调整R²值\n   - F统计量\n   - t统计量\n   - p值\n   - 残差分析\n\n4. 多元回归的假设检验：\n   - 正态性检验\n   - homoscedasticity检验\n   - 独立性检验\n   - 多重共线性检验\n\n5. 多元回归的应用：\n   - 销售预测\n   - 价格预测\n   - 需求预测\n   - 风险评估\n   - 客户流失预测\n\n通过本课时的学习，您将掌握多元回归分析的基本原理和应用方法，能够构建和应用多元回归模型进行预测。', pitfalls: '1. 假设条件不满足：多元回归的假设条件不满足，导致模型结果不可靠。\n2. 过拟合：模型过度拟合训练数据，导致对新数据的预测能力差。\n3. 多重共线性：自变量之间存在多重共线性，导致模型不稳定。\n4. 变量选择不当：选择了不相关或冗余的变量，导致模型性能下降。\n5. 计算复杂度：多元回归模型的计算复杂度较高，特别是当自变量较多时。', order: 6, duration: '60分钟' },
          { id: 7, course_id: 10, title: '模型评估与选择', content: '模型评估与选择是预测模型构建的重要环节。在本课时中，我们将详细学习：\n\n1. 模型评估的基本概念：\n   - 什么是模型评估\n   - 模型评估的重要性\n   - 模型评估的方法\n   - 模型评估的指标\n\n2. 模型评估指标：\n   - 回归模型评估指标（MAE、MSE、RMSE、R²等）\n   - 分类模型评估指标（准确率、召回率、F1分数、AUC等）\n   - 时间序列模型评估指标（MAPE、SMAPE、MASE等）\n\n3. 模型选择方法：\n   - 交叉验证\n   - 网格搜索\n   - 随机搜索\n   - 贝叶斯优化\n   - 正则化方法\n\n4. 模型比较：\n   - 统计检验\n   - 可视化比较\n   - 业务价值评估\n   - 计算效率评估\n\n5. 模型部署与监控：\n   - 模型部署\n   - 模型监控\n   - 模型更新\n   - 模型版本控制\n\n6. 案例分析：\n   - 销售预测模型评估\n   - 客户流失预测模型评估\n   - 库存预测模型评估\n   - 市场需求预测模型评估\n\n通过本课时的学习，您将掌握模型评估与选择的基本方法和技巧，能够评估和选择合适的预测模型。', pitfalls: '1. 评估指标选择不当：选择了不适合预测任务的评估指标，导致对模型性能的评估不准确。\n2. 过拟合：模型过度拟合训练数据，导致对新数据的预测能力差。\n3. 数据泄露：在模型评估过程中出现数据泄露，导致评估结果不准确。\n4. 模型选择偏见：在模型选择过程中存在偏见，导致选择了次优的模型。\n5. 缺乏业务视角：只关注技术指标，忽视了模型的业务价值。', order: 7, duration: '60分钟' },
          { id: 8, course_id: 10, title: '预测模型实战', content: '预测模型实战是预测模型课程的综合应用。在本课时中，我们将通过实际案例学习：\n\n1. 案例背景：\n   - 企业概况\n   - 业务挑战\n   - 数据情况\n   - 分析目标\n\n2. 数据收集和预处理：\n   - 数据来源\n   - 数据清洗\n   - 数据整合\n   - 特征工程\n\n3. 模型构建：\n   - 模型选择\n   - 模型训练\n   - 模型评估\n   - 模型优化\n\n4. 模型应用：\n   - 预测结果分析\n   - 业务建议\n   - 实施计划\n   - 效果评估\n\n5. 案例总结：\n   - 成功经验\n   - 教训和启示\n   - 最佳实践\n   - 未来展望\n\n通过本课时的学习，您将掌握预测模型的实际应用方法，能够独立完成预测模型项目。', pitfalls: '1. 数据质量问题：使用了质量差的数据，导致模型结果不可靠。\n2. 模型选择错误：选择了不适合数据特性的模型，导致预测结果不准确。\n3. 过拟合：模型过度拟合训练数据，导致对新数据的预测能力差。\n4. 缺乏业务知识：不了解业务背景，导致模型结果与实际业务需求不符。\n5. 模型部署困难：模型部署过程中遇到技术困难，导致模型无法实际应用。', order: 8, duration: '60分钟' },
          { id: 9, course_id: 10, title: '销售预测案例', content: '销售预测是预测模型的重要应用场景。在本课时中，我们将通过实际案例学习：\n\n1. 案例背景：\n   - 零售企业概况\n   - 销售数据情况\n   - 业务挑战\n   - 预测目标\n\n2. 数据收集和预处理：\n   - 销售数据收集\n   - 数据清洗\n   - 数据整合\n   - 特征工程\n\n3. 销售预测模型构建：\n   - 模型选择\n   - 模型训练\n   - 模型评估\n   - 模型优化\n\n4. 预测结果分析：\n   - 销售趋势分析\n   - 季节性分析\n   - 异常值分析\n   - 预测准确度评估\n\n5. 业务应用：\n   - 库存管理\n   - 人员安排\n   - 促销策略\n   - 财务规划\n\n6. 案例总结：\n   - 成功经验\n   - 教训和启示\n   - 最佳实践\n   - 未来展望\n\n通过本课时的学习，您将掌握销售预测的实际应用方法，能够独立完成销售预测项目。', pitfalls: '1. 数据质量问题：销售数据质量差，导致预测结果不可靠。\n2. 模型选择错误：选择了不适合销售数据特性的模型，导致预测结果不准确。\n3. 季节性处理不当：没有正确处理销售数据的季节性，导致预测结果偏差。\n4. 促销活动影响：没有考虑促销活动对销售的影响，导致预测结果偏差。\n5. 外部因素忽视：没有考虑外部因素（如经济环境、竞争对手活动等）对销售的影响，导致预测结果偏差。', order: 9, duration: '60分钟' },
          { id: 10, course_id: 10, title: '库存预测案例', content: '库存预测是预测模型的重要应用场景。在本课时中，我们将通过实际案例学习：\n\n1. 案例背景：\n   - 零售企业概况\n   - 库存数据情况\n   - 业务挑战\n   - 预测目标\n\n2. 数据收集和预处理：\n   - 库存数据收集\n   - 销售数据收集\n   - 数据清洗\n   - 数据整合\n   - 特征工程\n\n3. 库存预测模型构建：\n   - 模型选择\n   - 模型训练\n   - 模型评估\n   - 模型优化\n\n4. 预测结果分析：\n   - 库存水平分析\n   - 库存周转率分析\n   - 缺货风险分析\n   - 过剩库存分析\n\n5. 业务应用：\n   - 库存管理优化\n   - 采购计划制定\n   - 仓储空间规划\n   - 成本控制\n\n6. 案例总结：\n   - 成功经验\n   - 教训和启示\n   - 最佳实践\n   - 未来展望\n\n通过本课时的学习，您将掌握库存预测的实际应用方法，能够独立完成库存预测项目。', pitfalls: '1. 数据质量问题：库存数据质量差，导致预测结果不可靠。\n2. 模型选择错误：选择了不适合库存数据特性的模型，导致预测结果不准确。\n3. 需求波动忽视：没有考虑需求波动对库存的影响，导致预测结果偏差。\n4. 供应 lead time 忽视：没有考虑供应 lead time 对库存的影响，导致预测结果偏差。\n5. 季节性处理不当：没有正确处理库存数据的季节性，导致预测结果偏差。', order: 10, duration: '60分钟' },
          { id: 11, course_id: 10, title: '客户流失预测', content: '客户流失预测是预测模型的重要应用场景。在本课时中，我们将通过实际案例学习：\n\n1. 案例背景：\n   - 企业概况\n   - 客户数据情况\n   - 业务挑战\n   - 预测目标\n\n2. 数据收集和预处理：\n   - 客户数据收集\n   - 交易数据收集\n   - 数据清洗\n   - 数据整合\n   - 特征工程\n\n3. 客户流失预测模型构建：\n   - 模型选择\n   - 模型训练\n   - 模型评估\n   - 模型优化\n\n4. 预测结果分析：\n   - 客户流失风险分析\n   - 客户细分\n   - 流失原因分析\n   - 预测准确度评估\n\n5. 业务应用：\n   - 客户保留策略\n   - 个性化营销\n   - 客户服务优化\n   - 客户价值管理\n\n6. 案例总结：\n   - 成功经验\n   - 教训和启示\n   - 最佳实践\n   - 未来展望\n\n通过本课时的学习，您将掌握客户流失预测的实际应用方法，能够独立完成客户流失预测项目。', pitfalls: '1. 数据质量问题：客户数据质量差，导致预测结果不可靠。\n2. 模型选择错误：选择了不适合客户流失数据特性的模型，导致预测结果不准确。\n3. 特征选择不当：选择了不相关或冗余的特征，导致模型性能下降。\n4. 类别不平衡：客户流失数据通常存在类别不平衡问题，导致模型偏向于预测大多数类。\n5. 缺乏业务知识：不了解客户流失的业务原因，导致模型结果与实际业务需求不符。', order: 11, duration: '60分钟' },
          { id: 12, course_id: 10, title: '预测模型项目总结', content: '预测模型项目总结是预测模型课程的最后环节。在本课时中，我们将详细学习：\n\n1. 项目回顾：\n   - 项目目标达成情况\n   - 技术实现总结\n   - 遇到的挑战\n   - 解决方案\n\n2. 经验教训：\n   - 数据质量\n   - 模型选择\n   - 特征工程\n   - 模型评估\n   - 模型部署\n\n3. 最佳实践：\n   - 预测模型开发规范\n   - 数据处理最佳实践\n   - 模型选择最佳实践\n   - 模型评估最佳实践\n   - 模型部署最佳实践\n\n4. 行业趋势：\n   - 预测模型技术发展\n   - 自动化机器学习\n   - 深度学习在预测中的应用\n   - 实时预测\n   - 边缘计算\n\n5. 未来展望：\n   - 技术改进方向\n   - 应用场景拓展\n   - 与其他技术的融合\n   - 标准化和规范化\n   - 伦理和隐私考虑\n\n6. 学习资源：\n   - 书籍推荐\n   - 在线课程\n   - 工具和库\n   - 社区和论坛\n\n通过本课时的学习，您将总结预测模型项目的经验教训，为未来的预测模型项目提供参考。', pitfalls: '1. 总结不全面：没有全面总结项目经验和教训，导致无法为未来项目提供参考。\n2. 经验教训分析不深入：对经验教训的分析不够深入，无法从中学习。\n3. 最佳实践提炼不足：没有提炼出有价值的最佳实践，影响后续项目。\n4. 行业趋势把握不准确：对行业趋势的把握不准确，导致技术选型落后。\n5. 未来规划不实际：未来规划过于理想化，无法实现。', order: 12, duration: '60分钟' }
        ]
      };
      
      // 从模拟数据中获取课时
      const courseLessons = mockLessons[courseId as keyof typeof mockLessons];
      if (!courseLessons) {
        set({ error: '课程不存在', isLoading: false });
        return;
      }
      
      const lesson = courseLessons.find(l => l.id === lessonId);
      if (!lesson) {
        set({ error: '课时不存在', isLoading: false });
        return;
      }
      
      // 添加缺失的属性以满足TypeScript类型要求
      const lessonWithRequiredProps = {
        ...lesson,
        order_index: lesson.order,
        created_at: new Date().toISOString()
      };
      
      set({ currentLesson: lessonWithRequiredProps, isLoading: false });
    } catch (error) {
      console.error('加载课时失败:', error);
      set({ isLoading: false });
    }
  },
  
  loadProgress: async () => {
    const user = get().user;
    if (!user) return;
    
    const { data, error } = await supabase
      .from('progress')
      .select('*')
      .eq('user_id', user.id);
    
    if (error) {
      set({ error: error.message });
      return;
    }
    
    set({ progress: data || [] });
  },
  
  updateProgress: async (courseId, lessonId, completed) => {
    const user = get().user;
    if (!user) return;
    
    const { data, error } = await supabase
      .from('progress')
      .upsert({
        user_id: user.id,
        course_id: courseId,
        lesson_id: lessonId,
        completed,
        completion_date: completed ? new Date().toISOString() : null,
        last_accessed: new Date().toISOString()
      })
      .select();
    
    if (error) {
      set({ error: error.message });
      return;
    }
    
    // Update local progress
    const progress = get().progress;
    const existingIndex = progress.findIndex(
      p => p.user_id === user.id && p.course_id === courseId && p.lesson_id === lessonId
    );
    
    if (existingIndex >= 0) {
      progress[existingIndex] = data[0];
    } else {
      progress.push(data[0]);
    }
    
    set({ progress });
  },
  
  loadAchievements: async () => {
    const user = get().user;
    if (!user) return;
    
    // Load all achievements
    const { data: achievements, error: achievementsError } = await supabase
      .from('achievements')
      .select('*');
    
    if (achievementsError) {
      set({ error: achievementsError.message });
      return;
    }
    
    // Load user achievements
    const { data: userAchievements, error: userAchievementsError } = await supabase
      .from('user_achievements')
      .select('achievement_id')
      .eq('user_id', user.id);
    
    if (userAchievementsError) {
      set({ error: userAchievementsError.message });
      return;
    }
    
    // Get the actual achievement objects for user achievements
    const userAchievementObjects = achievements.filter(achievement => 
      userAchievements.some(ua => ua.achievement_id === achievement.id)
    );
    
    set({ 
      achievements: achievements || [],
      userAchievements: userAchievementObjects
    });
  },
  
  resetError: () => {
    set({ error: null });
  }
}));

// Helper function to get progress for a specific lesson
export const getLessonProgress = (courseId: number, lessonId: number) => {
  const { progress } = useStore.getState();
  return progress.find(p => p.course_id === courseId && p.lesson_id === lessonId);
};

// Helper function to get overall course progress
export const getCourseProgress = (courseId: number) => {
  const { progress, currentCourse } = useStore.getState();
  if (!currentCourse) return 0;
  
  const courseLessons = currentCourse.lessons?.length || 0;
  if (courseLessons === 0) return 0;
  
  const completedLessons = progress.filter(
    p => p.course_id === courseId && p.completed
  ).length;
  
  return Math.round((completedLessons / courseLessons) * 100);
};